{"format":"sql","data":"-- Database Export\n-- Generated on: 2026-07-17T06:56:46.247Z\n-- Format: SQL\n-- Include Data: true\n-- Row Limit: 1000 rows per table\n\n-- Table: access_requests\nCREATE TABLE IF NOT EXISTS access_requests (id uuid NOT NULL DEFAULT gen_random_uuid(), full_name text NOT NULL, company_name text NOT NULL, company_website text, industry text NOT NULL, company_size text, work_email text NOT NULL, phone_number text, role_in_company text, num_roles text, hiring_categories ARRAY DEFAULT '{}'::text[], hiring_timeline text, additional_notes text, request_type text NOT NULL DEFAULT 'access_application'::text, status text NOT NULL DEFAULT 'pending'::text, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());\n\n-- RLS enabled for table: access_requests\nALTER TABLE access_requests ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: access_requests\nCREATE POLICY \"Anyone can submit access request\" ON access_requests FOR INSERT TO public WITH CHECK (((work_email IS NOT NULL) AND (full_name IS NOT NULL) AND (company_name IS NOT NULL)));\nCREATE POLICY \"Super admin manages access requests\" ON access_requests FOR ALL TO authenticated USING ((( SELECT profiles.role\n   FROM profiles\n  WHERE (profiles.id = ( SELECT auth.uid() AS uid))) = 'super_admin'::text));\nCREATE POLICY project_admin_policy ON access_requests FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: activity\nCREATE TABLE IF NOT EXISTS activity (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, type text, title text, description text, time_ago text, actor text, actor_avatar text, meta text, created_at timestamptz DEFAULT now());\n\n-- Indexes for table: activity\nCREATE INDEX idx_activity_user_id ON public.activity USING btree (user_id);\n\n-- RLS enabled for table: activity\nALTER TABLE activity ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: activity\nCREATE POLICY \"Super admin sees all activity\" ON activity FOR ALL TO authenticated USING ((( SELECT profiles.role\n   FROM profiles\n  WHERE (profiles.id = ( SELECT auth.uid() AS uid))) = 'super_admin'::text));\nCREATE POLICY \"Users insert own activity\" ON activity FOR INSERT TO authenticated WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Users see own activity\" ON activity FOR SELECT TO authenticated USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON activity FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Data for table: activity\nINSERT INTO activity (id, user_id, type, title, description, time_ago, actor, actor_avatar, meta, created_at) VALUES ('0cae2f41-258a-473c-9449-500cbd3258e1', NULL, 'view', 'Profile viewed', 'Profile viewed by Google', '2 hours ago', 'Google', 'https://www.google.com/favicon.ico', NULL, '2026-03-16T13:10:59.154Z');\nINSERT INTO activity (id, user_id, type, title, description, time_ago, actor, actor_avatar, meta, created_at) VALUES ('f4f63131-9499-4255-b304-f74b14d2d966', '464fd40c-d5dd-4aca-8a8c-c1dad7a9149b', 'signup', NULL, 'Joined Talentmesh as candidate', NULL, NULL, NULL, NULL, '2026-04-06T07:12:53.747Z');\nINSERT INTO activity (id, user_id, type, title, description, time_ago, actor, actor_avatar, meta, created_at) VALUES ('876159b0-a51d-46bc-9fb7-60bf120583b0', '18d329f1-7301-4359-91b4-595f948f4342', 'application_update', 'Application Status Update', 'Admin updated application for Anuj Patel to reviewing', NULL, NULL, NULL, '{\"status\": \"reviewing\", \"actor_id\": \"18d329f1-7301-4359-91b4-595f948f4342\", \"actor_type\": \"admin\", \"application_id\": \"0f100e2e-8cba-4bdc-a394-473e1049df18\"}', '2026-06-08T10:14:04.060Z');\nINSERT INTO activity (id, user_id, type, title, description, time_ago, actor, actor_avatar, meta, created_at) VALUES ('6e94838f-5c9e-4d24-8757-a33120fe14b0', '18d329f1-7301-4359-91b4-595f948f4342', 'application_update', 'Application Status Update', 'Updated applicatio