(id, user_id, type, title, description, time_ago, actor, actor_avatar, meta, created_at) VALUES ('f5f75164-068c-47a1-8355-80805d69bfe4', '20b164ec-827e-4a40-9d5d-0b16743f7771', 'signup_verify', NULL, 'Verified email and joined as candidate', NULL, NULL, NULL, NULL, '2026-06-18T12:40:21.619Z');\n\n-- Table: admin_invites\nCREATE TABLE IF NOT EXISTS admin_invites (id uuid NOT NULL DEFAULT gen_random_uuid(), token_hash text NOT NULL, used_by uuid, used_at timestamptz, created_at timestamptz DEFAULT now());\n\n-- Indexes for table: admin_invites\nCREATE UNIQUE INDEX admin_invites_token_hash_key ON public.admin_invites USING btree (token_hash);\nCREATE INDEX idx_admin_invites_used_by ON public.admin_invites USING btree (used_by);\n\n-- Foreign key constraints for table: admin_invites\nALTER TABLE admin_invites ADD CONSTRAINT admin_invites_used_by_fkey FOREIGN KEY (used_by) REFERENCES profiles (id);\n\n-- RLS enabled for table: admin_invites\nALTER TABLE admin_invites ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: admin_invites\nCREATE POLICY project_admin_policy ON admin_invites FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: admin_permissions\nCREATE TABLE IF NOT EXISTS admin_permissions (id uuid NOT NULL DEFAULT gen_random_uuid(), admin_id uuid NOT NULL, permission text NOT NULL, granted_by uuid, granted_at timestamptz DEFAULT now());\n\n-- Indexes for table: admin_permissions\nCREATE UNIQUE INDEX admin_permissions_admin_id_permission_key ON public.admin_permissions USING btree (admin_id, permission);\nCREATE INDEX idx_admin_permissions_granted_by ON public.admin_permissions USING btree (granted_by);\n\n-- Foreign key constraints for table: admin_permissions\nALTER TABLE admin_permissions ADD CONSTRAINT admin_permissions_admin_id_fkey FOREIGN KEY (admin_id) REFERENCES profiles (id) ON DELETE CASCADE;\nALTER TABLE admin_permissions ADD CONSTRAINT admin_permissions_granted_by_fkey FOREIGN KEY (granted_by) REFERENCES profiles (id);\n\n-- RLS enabled for table: admin_permissions\nALTER TABLE admin_permissions ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: admin_permissions\nCREATE POLICY project_admin_policy ON admin_permissions FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: admin_users\nCREATE TABLE IF NOT EXISTS admin_users (user_id uuid NOT NULL);\n\n-- RLS enabled for table: admin_users\nALTER TABLE admin_users ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: admin_users\nCREATE POLICY project_admin_policy ON admin_users FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Data for table: admin_users\nINSERT INTO admin_users (user_id) VALUES ('18d329f1-7301-4359-91b4-595f948f4342');\nINSERT INTO admin_users (user_id) VALUES ('dbba6fee-7e1b-43ac-91b0-2ec11fa7cf63');\nINSERT INTO admin_users (user_id) VALUES ('0015ef1a-3eef-46d4-bbe6-1b73d154f02a');\nINSERT INTO admin_users (user_id) VALUES ('a3a26905-3e26-4a11-809d-19269f321755');\nINSERT INTO admin_users (user_id) VALUES ('323a9ebe-e7d0-40fc-bc34-e746a6c40c4a');\nINSERT INTO admin_users (user_id) VALUES ('3019d110-93a6-4b4f-9d37-abbeebfb714f');\nINSERT INTO admin_users (user_id) VALUES ('ca708a70-4336-4709-8d68-3f620a53e147');\n\n-- Table: ai_interviews\nCREATE TABLE IF NOT EXISTS ai_interviews (id uuid NOT NULL DEFAULT gen_random_uuid(), questions jsonb, createdat timestamptz DEFAULT now(), duration integer, status text DEFAULT 'pending'::text, results jsonb, candidate_id uuid);\n\n-- Indexes for table: ai_interviews\nCREATE INDEX idx_ai_interviews_candidate_id ON public.ai_interviews USING btree (candidate_id);\n\n-- Foreign key constraints for table: ai_interviews\nALTER TABLE ai_interviews ADD CONSTRAINT ai_interviews_candidate_id_fkey FOREIGN KEY (candidate_id) REFERENCES profiles (id);\n\n-- RLS enabled for table: ai_interviews\nALTER TABLE ai_interviews ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: ai_interviews\nCREATE POLICY \"Candidates insert own ai interviews\" ON ai_interviews FOR INSERT TO authenticated WITH CHECK ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Candidates see own ai interviews\" ON ai_interviews FOR SELECT TO authenticated USING ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Super admin sees all ai interviews\" ON ai_interviews FOR ALL TO authenticated USING ((( SELECT profiles.role\n   FROM profiles\n  WHERE (profiles.id = ( SELECT auth.uid() AS uid))) = 'super_admin'::text));\nCREATE POLICY project_admin_policy ON ai_interviews FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: ai_suggestion_cache\nCREATE TABLE IF NOT EXISTS ai_suggestion_cache (query_key text NOT NULL, suggestions jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz DEFAULT now());\n\n-- RLS enabled for table: ai_suggestion_cache\nALTER TABLE ai_suggestion_cache ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: ai_suggestion_cache\nCREATE POLICY project_admin_policy ON ai_suggestion_cache FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: announcement_dismissals\nCREATE TABLE IF NOT EXISTS announcement_dismissals (id uuid NOT NULL DEFAULT gen_random_uuid(), announcement_id uuid NOT NULL, user_id uuid NOT NULL, dismissed_at timestamptz DEFAULT now());\n\n-- Indexes for table: announcement_dismissals\nCREATE UNIQUE INDEX announcement_dismissals_announcement_id_user_id_key ON public.announcement_dismissals USING btree (announcement_id, user_id);\nCREATE INDEX idx_announcement_dismissals_user_id ON public.announcement_dismissals USING btree (user_id);\n\n-- Foreign key constraints for table: announcement_dismissals\nALTER TABLE announcement_dismissals ADD CONSTRAINT announcement_dismissals_announcement_id_fkey FOREIGN KEY (announcement_id) REFERENCES announcements (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: announcement_dismissals\nALTER TABLE announcement_dismissals ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: announcement_dismissals\nCREATE POLICY \"Users can insert own dismissals\" ON announcement_dismissals FOR INSERT TO public WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Users can read own dismissals\" ON announcement_dismissals FOR SELECT TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY admin_bypass_dismissals ON announcement_dismissals FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON announcement_dismissals FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: announcements\nCREATE TABLE IF NOT EXISTS announcements (id uuid NOT NULL DEFAULT gen_random_uuid(), title text NOT NULL, message text NOT NULL, type text DEFAULT 'info'::text, is_active boolean DEFAULT true, show_as_banner boolean DEFAULT false, target_roles ARRAY DEFAULT ARRAY['all'::text], scheduled_at timestamptz, expires_at timestamptz, view_count integer DEFAULT 0, dismiss_count integer DEFAULT 0, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), image_url text);\n\n-- RLS enabled for table: announcements\nALTER TABLE announcements ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: announcements\nCREATE POLICY \"Admins can manage announcements\" ON announcements FOR ALL TO public USING (is_admin());\nCREATE POLICY \"Anyone can read active announcements\" ON announcements FOR SELECT TO public USING (true);\nCREATE POLICY admin_bypass_announcements ON announcements FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON announcements FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: application_events\nCREATE TABLE IF NOT EXISTS application_events (id uuid NOT NULL DEFAULT gen_random_uuid(), application_id uuid, event_type text, created_at timestamptz DEFAULT now());\n\n-- Indexes for table: application_events\nCREATE INDEX idx_application_events_application_id ON public.application_events USING btree (application_id);\n\n-- Foreign key constraints for table: application_events\nALTER TABLE application_events ADD CONSTRAINT application_events_application_id_fkey FOREIGN KEY (application_id) REFERENCES applications (id);\n\n-- RLS enabled for table: application_events\nALTER TABLE application_events ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: application_events\nCREATE POLICY admin_bypass ON application_events FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON application_events FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: application_status_history\nCREATE TABLE IF NOT EXISTS application_status_history (id uuid NOT NULL DEFAULT gen_random_uuid(), application_id uuid NOT NULL, from_status text, to_status text NOT NULL, changed_by uuid, actor_type text, metadata jsonb DEFAULT '{}'::jsonb, note text, changed_at timestamptz DEFAULT now());\n\n-- Indexes for table: application_status_history\nCREATE INDEX idx_application_history_actor ON public.application_status_history USING btree (changed_by);\nCREATE INDEX idx_application_history_actor_time ON public.application_status_history USING btree (actor_type, changed_at DESC);\nCREATE INDEX idx_application_history_application ON public.application_status_history USING btree (application_id);\nCREATE INDEX idx_application_history_changed_at ON public.application_status_history USING btree (changed_at DESC);\n\n-- Foreign key constraints for table: application_status_history\nALTER TABLE application_status_history ADD CONSTRAINT application_status_history_application_id_fkey FOREIGN KEY (application_id) REFERENCES applications (id) ON DELETE CASCADE;\nALTER TABLE application_status_history ADD CONSTRAINT application_status_history_changed_by_fkey FOREIGN KEY (changed_by) REFERENCES profiles (id) ON DELETE SET NULL;\n\n-- RLS enabled for table: application_status_history\nALTER TABLE application_status_history ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: application_status_history\nCREATE POLICY admin_bypass ON application_status_history FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON application_status_history FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY status_history_select_own ON application_status_history FOR SELECT TO public USING ((EXISTS ( SELECT 1\n   FROM applications a\n  WHERE ((a.id = application_status_history.application_id) AND (a.candidate_id = ( SELECT auth.uid() AS uid))))));\nCREATE POLICY status_history_select_recruiter ON application_status_history FOR SELECT TO public USING ((EXISTS ( SELECT 1\n   FROM (applications a\n     JOIN jobs j ON ((j.id = a.job_id)))\n  WHERE ((a.id = application_status_history.application_id) AND (j.recruiter_id = ( SELECT auth.uid() AS uid))))));\n\n-- Data for table: application_status_history\nINSERT INTO application_status_history (id, application_id, from_status, to_status, changed_by, actor_type, metadata, note, changed_at) VALUES ('f46689e1-fefd-4dd9-bc8b-e8ea86a4a2ac', '8c203104-f5d7-49ad-923e-b11190cec51e', NULL, 'applied', NULL, 'system', '{}', 'Application submitted', '2026-06-11T12:51:28.235Z');\nINSERT INTO application_status_history (id, application_id, from_status, to_status, changed_by, actor_type, metadata, note, changed_at) VALUES ('b17b0010-7d86-4c8d-b12b-defe3173c968', 'e9b29734-0378-4ce7-bbbd-520cf757479b', NULL, 'applied', NULL, 'system', '{}', 'Application submitted', '2026-06-11T12:52:40.242Z');\nINSERT INTO application_status_history (id, application_id, from_status, to_status, changed_by, actor_type, metadata, note, changed_at) VALUES ('c6aee51f-dc7e-46f1-ad8b-69c357ee9ebb', 'f325bb25-7391-461e-b9a5-496ff71387ad', NULL, 'applied', NULL, 'system', '{}', 'Application submitted', '2026-06-11T12:53:41.296Z');\nINSERT INTO application_status_history (id, application_id, from_status, to_status, changed_by, actor_type, metadata, note, changed_at) VALUES ('433722c8-301b-487c-8