d96d17dc', NULL, 'applied', NULL, 'system', '{}', 'Application submitted', '2026-06-11T12:29:36.475Z');\nINSERT INTO application_status_history (id, application_id, from_status, to_status, changed_by, actor_type, metadata, note, changed_at) VALUES ('648bca88-5eeb-4936-807a-b3b65526e84b', 'e17140fd-253e-48ab-982f-fbad99e7e8f4', NULL, 'applied', NULL, 'system', '{}', 'Application submitted', '2026-06-11T12:32:21.772Z');\nINSERT INTO application_status_history (id, application_id, from_status, to_status, changed_by, actor_type, metadata, note, changed_at) VALUES ('34b86f51-6ee9-4962-9598-be15fc2bb971', '631e8a78-6a48-4680-acc9-04cd51f33ea5', NULL, 'applied', NULL, 'system', '{}', 'Application submitted', '2026-06-11T12:32:29.029Z');\nINSERT INTO application_status_history (id, application_id, from_status, to_status, changed_by, actor_type, metadata, note, changed_at) VALUES ('51c6148b-b28d-4cab-9ff6-ddcc96438b96', '8bf18002-3051-491a-b209-978f20edb2bc', NULL, 'applied', NULL, 'system', '{}', 'Application submitted', '2026-06-11T12:39:53.976Z');\nINSERT INTO application_status_history (id, application_id, from_status, to_status, changed_by, actor_type, metadata, note, changed_at) VALUES ('fe1b84b4-4a12-4902-afba-d0f5fd0a770e', 'f12ac6ba-30fd-43a7-ad2e-520eeb859dff', NULL, 'applied', NULL, 'system', '{}', 'Application submitted', '2026-06-11T12:40:01.935Z');\n\n-- Table: applications\nCREATE TABLE IF NOT EXISTS applications (id uuid NOT NULL DEFAULT gen_random_uuid(), job_id uuid NOT NULL, candidate_id uuid NOT NULL, status text DEFAULT 'applied'::text, cover_letter text, ai_match_score integer DEFAULT 0, stage_index integer DEFAULT 0, recruiter_notes text, rejection_reason text, applied_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(), apply_type text DEFAULT 'quick'::text, resume_url text, screening_answers jsonb, resume_id uuid, resume_snapshot_key text);\n\n-- Indexes for table: applications\nCREATE INDEX idx_applications_candidate ON public.applications USING btree (candidate_id, applied_at DESC);\nCREATE INDEX idx_applications_candidate_id ON public.applications USING btree (candidate_id);\nCREATE INDEX idx_applications_job ON public.applications USING btree (job_id, status);\nCREATE INDEX idx_applications_job_id ON public.applications USING btree (job_id);\nCREATE INDEX idx_applications_resume_id ON public.applications USING btree (resume_id);\nCREATE INDEX idx_applications_status ON public.applications USING btree (status);\nCREATE INDEX idx_apps_cand ON public.applications USING btree (candidate_id, applied_at DESC);\nCREATE UNIQUE INDEX idx_unique_candidate_job_application ON public.applications USING btree (candidate_id, job_id) WHERE (status <> 'withdrawn'::text);\n\n-- Foreign key constraints for table: applications\nALTER TABLE applications ADD CONSTRAINT applications_candidate_id_fkey FOREIGN KEY (candidate_id) REFERENCES candidate_profiles (id) ON DELETE CASCADE;\nALTER TABLE applications ADD CONSTRAINT applications_candidate_user_id_fkey FOREIGN KEY (candidate_id) REFERENCES profiles (id) ON DELETE CASCADE;\nALTER TABLE applications ADD CONSTRAINT applications_job_id_fkey FOREIGN KEY (job_id) REFERENCES jobs (id);\nALTER TABLE applications ADD CONSTRAINT applications_resume_id_fkey FOREIGN KEY (resume_id) REFERENCES candidate_resumes (id) ON DELETE SET NULL;\n\n-- RLS enabled for table: applications\nALTER TABLE applications ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: applications\nCREATE POLICY \"Admins can view all applications\" ON applications FOR SELECT TO authenticated USING (is_admin());\nCREATE POLICY \"Candidates can insert applications\" ON applications FOR INSERT TO public WITH CHECK ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Candidates can view own applications\" ON applications FOR SELECT TO public USING ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Recruiters can update application status\" ON applications FOR UPDATE TO public USING ((EXISTS ( SELECT 1\n   FROM (jobs j\n     JOIN recruiter_profiles rp ON ((rp.company_id = j.company_id)))\n  WHERE ((j.id = applications.job_id) AND (rp.id = ( SELECT auth.uid() AS uid))))));\nCREATE POLICY \"Recruiters can view job applications\" ON applications FOR SELECT TO public USING ((EXISTS ( SELECT 1\n   FROM (jobs j\n     JOIN recruiter_profiles rp ON ((rp.company_id = j.company_id)))\n  WHERE ((j.id = applications.job_id) AND (rp.id = ( SELECT auth.uid() AS uid))))));\nCREATE POLICY admin_bypass ON applications FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY applications_insert_candidate ON applications FOR INSERT TO public WITH CHECK ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY applications_self ON applications FOR SELECT TO public USING ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY apps_insert_own ON applications FOR INSERT TO public WITH CHECK ((( SELECT auth.uid() AS uid) = candidate_id));\nCREATE POLICY apps_recruiter_update ON applications FOR UPDATE TO public USING ((EXISTS ( SELECT 1\n   FROM jobs j\n  WHERE ((j.id = applications.job_id) AND (j.recruiter_id = ( SELECT auth.uid() AS uid))))));\nCREATE POLICY apps_recruiter_view ON applications FOR SELECT TO public USING ((EXISTS ( SELECT 1\n   FROM jobs j\n  WHERE ((j.id = applications.job_id) AND (j.recruiter_id = ( SELECT auth.uid() AS uid))))));\nCREATE POLICY apps_select_own ON applications FOR SELECT TO public USING ((( SELECT auth.uid() AS uid) = candidate_id));\nCREATE POLICY apps_update_own ON applications FOR UPDATE TO public USING ((( SELECT auth.uid() AS uid) = candidate_id));\n\n-- Triggers for table: applications\nCREATE TRIGGER tr_apps_update BEFORE UPDATE ON applications FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER trigger_check_direct_application_status_update BEFORE UPDATE ON applications FOR EACH ROW EXECUTE FUNCTION check_direct_application_status_update();\nCREATE TRIGGER trigger_log_application_status_change AFTER INSERT ON applications FOR EACH ROW EXECUTE FUNCTION log_application_status_change();\nCREATE TRIGGER trigger_log_application_status_change AFTER UPDATE ON applications FOR EACH ROW EXECUTE FUNCTION log_application_status_change();\nCREATE TRIGGER trigger_maintain_resume_upload_count AFTER INSERT ON applications FOR EACH ROW EXECUTE FUNCTION maintain_resume_upload_count();\nCREATE TRIGGER trigger_maintain_resume_upload_count AFTER DELETE ON applications FOR EACH ROW EXECUTE FUNCTION maintain_resume_upload_count();\nCREATE TRIGGER trigger_maintain_resume_upload_count AFTER UPDATE ON applications FOR EACH ROW EXECUTE FUNCTION maintain_resume_upload_count();\nCREATE TRIGGER trigger_set_updated_at BEFORE UPDATE ON applications FOR EACH ROW EXECUTE FUNCTION set_current_timestamp_updated_at();\nCREATE TRIGGER trigger_update_job_applications_count AFTER INSERT ON applications FOR EACH ROW EXECUTE FUNCTION update_job_applications_count();\nCREATE TRIGGER trigger_update_job_applications_count AFTER DELETE ON applications FOR EACH ROW EXECUTE FUNCTION update_job_applications_count();\nCREATE TRIGGER trigger_update_job_applications_count AFTER UPDATE ON applications FOR EACH ROW EXECUTE FUNCTION update_job_applications_count();\nCREATE TRIGGER update_applications_updated_at BEFORE UPDATE ON applications FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n\n-- Data for table: applications\nINSERT INTO applications (id, job_id, candidate_id, status, cover_letter, ai_match_score, stage_index, recruiter_notes, rejection_reason, applied_at, updated_at, apply_type, resume_url, screening_answers, resume_id, resume_snapshot_key) VALUES ('6a19ece7-0bb9-4218-9240-feb6ee9994e6', 'a21df5b6-30d6-47d4-8d40-f451f38caf29', '01eb08b9-43b5-4b67-85a2-8b140de3c334', 'applied', 'Candidate B Quick Apply cover letter', 0, 0, NULL, NULL, '2026-06-11T12:29:27.184Z', '2026-06-11T12:29:27.184Z', 'quick', 'https://sytk3jgv.ap-southeast.insforge.app/api/storage/buckets/a