 audit_log (id, actor_id, action, table_name, record_id, old_data, new_data, metadata, ip_address, user_agent, status, created_at) VALUES ('fa745338-5448-4e82-b766-53a2375ff2b4', '18d329f1-7301-4359-91b4-595f948f4342', 'recruiter_document_view', NULL, NULL, NULL, NULL, '{\"resource_key\":\"kyc_1780120463628_Gemini_Generated_Image_462bwu462bwu462b.png\",\"resource_type\":\"recruiter_document\"}', NULL, NULL, 'success', '2026-06-22T06:41:17.609Z');\n\n-- Table: auth_attempts\nCREATE TABLE IF NOT EXISTS auth_attempts (email text NOT NULL, ip text, failures integer DEFAULT 0, blocked_until timestamptz, updated_at timestamptz DEFAULT now());\n\n-- RLS enabled for table: auth_attempts\nALTER TABLE auth_attempts ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: auth_attempts\nCREATE POLICY \"Service role can manage auth attempts\" ON auth_attempts FOR ALL TO public USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON auth_attempts FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: auth_events\nCREATE TABLE IF NOT EXISTS auth_events (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, event_type text NOT NULL, ip_address text, user_agent text, created_at timestamptz DEFAULT now());\n\n-- Indexes for table: auth_events\nCREATE INDEX idx_auth_events_user_id ON public.auth_events USING btree (user_id);\n\n-- RLS enabled for table: auth_events\nALTER TABLE auth_events ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: auth_events\nCREATE POLICY \"Users can view own auth events\" ON auth_events FOR SELECT TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY admin_bypass ON auth_events FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON auth_events FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: authorization_events\nCREATE TABLE IF NOT EXISTS authorization_events (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, company_id uuid, event_type text NOT NULL, resource text NOT NULL, reason text, request_id text, route text, timestamp timestamptz DEFAULT now());\n\n-- Indexes for table: authorization_events\nCREATE INDEX idx_authorization_events_company_id ON public.authorization_events USING btree (company_id);\nCREATE INDEX idx_authorization_events_user_id ON public.authorization_events USING btree (user_id);\n\n-- Foreign key constraints for table: authorization_events\nALTER TABLE authorization_events ADD CONSTRAINT authorization_events_company_id_fkey FOREIGN KEY (company_id) REFERENCES company_profiles (id) ON DELETE SET NULL;\nALTER TABLE authorization_events ADD CONSTRAINT authorization_events_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE SET NULL;\n\n-- RLS enabled for table: authorization_events\nALTER TABLE authorization_events ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: authorization_events\nCREATE POLICY admin_bypass ON authorization_events FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON authorization_events FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY recruiter_read_audit ON authorization_events FOR SELECT TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\n\n-- Table: blog\nCREATE TABLE IF NOT EXISTS blog (id uuid NOT NULL DEFAULT gen_random_uuid(), title text NOT NULL, slug text NOT NULL, content text, excerpt text, cover_image text, author_id uuid, category text, status text DEFAULT 'draft'::text, created_at timestamptz DEFAULT now());\n\n-- Indexes for table: blog\nCREATE UNIQUE INDEX blog_slug_key ON public.blog USING btree (slug);\nCREATE INDEX idx_blog_author_id ON public.blog USING btree (author_id);\n\n-- Foreign key constraints for table: blog\nALTER TABLE blog ADD CONSTRAINT blog_author_id_fkey FOREIGN KEY (author_id) REFERENCES profiles (id) ON DELETE SET NULL;\n\n-- RLS enabled for table: blog\nALTER TABLE blog ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: blog\nCREATE POLICY \"Anyone can read published blog posts\" ON blog FOR SELECT TO public USING ((status = 'published'::text));\nCREATE POLICY \"Super admin manages blog\" ON blog FOR ALL TO authenticated USING ((( SELECT profiles.role\n   FROM profiles\n  WHERE (profiles.id = ( SELECT auth.uid() AS uid))) = 'super_admin'::text));\nCREATE POLICY project_admin_policy ON blog FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Data for table: blog\nINSERT INTO blog (id, title, slug, content, excerpt, cover_image, author_id, category, status, created_at) VALUES ('1901f1c5-8ee8-49f2-93da-1eb23f3c4140', 'The Making of Anuj Patel', 'the-making-of-anuj-patel', 'Anuj uohorh whruoh nwjbjocushjsfnoouefhdcsmknoubdkn  nowbbuow hnwjb owuhdoun daoa', 'asdfghjkl', 'https://sytk3jgv.ap-southeast.insforge.app/api/storage/buckets/blog_images_final/objects/blog%2F1777442167923_WhatsApp_Image_2026-04-29_at_11.24.14_AM.jpeg', '18d329f1-7301-4359-91b4-595f948f4342', 'Success Stories', 'published', '2026-04-29T05:56:53.670Z');\n\n-- Table: candidate_profiles\nCREATE TABLE IF NOT EXISTS candidate_profiles (id uuid NOT NULL, headline text, skills ARRAY DEFAULT '{}'::text[], experience_years integer DEFAULT 0, education jsonb DEFAULT '[]'::jsonb, work_history jsonb DEFAULT '[]'::jsonb, resume_url text, linkedin_url text, github_url text, portfolio_url text, salary_min numeric, salary_max numeric, currency text DEFAULT 'INR'::text, job_types ARRAY, preferred_locations ARRAY, open_to_remote boolean DEFAULT true, profile_strength integer DEFAULT 0, is_visible boolean DEFAULT true, updated_at timestamptz DEFAULT now(), resume_path text, primary_resume_id uuid, is_discoverable boolean DEFAULT true);\n\n-- Indexes for table: candidate_profiles\nCREATE INDEX idx_cand_skills ON public.candidate_profiles USING gin (skills);\nCREATE INDEX idx_candidate_profiles_discoverable ON public.candidate_profiles USING btree (is_discoverable);\nCREATE INDEX idx_candidate_profiles_primary_resume_id ON public.candidate_profiles USING btree (primary_resume_id);\nCREATE INDEX idx_candidate_skills ON public.candidate_profiles USING gin (skills);\n\n-- Foreign key constraints for table: candidate_profiles\nALTER TABLE candidate_profiles ADD CONSTRAINT candidate_profiles_primary_resume_id_fkey FOREIGN KEY (primary_resume_id) REFERENCES candidate_resumes (id) ON DELETE SET NULL;\nALTER TABLE candidate_profiles ADD CONSTRAINT fk_candidate_user FOREIGN KEY (id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: candidate_profiles\nALTER TABLE candidate_profiles ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: candidate_profiles\nCREATE POLICY \"Candidate own profile\" ON candidate_profiles FOR ALL TO public USING ((( SELECT auth.uid() AS uid) = id));\nCREATE POLICY candidate_profiles_insert ON candidate_profiles FOR INSERT TO public WITH CHECK ((id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY candidate_profiles_recruiter_select ON candidate_profiles FOR SELECT TO public USING ((EXISTS ( SELECT 1\n   FROM (applications a\n     JOIN jobs j ON ((j.id = a.job_id)))\n  WHERE ((a.candidate_id = candidate_profiles.id) AND (j.recruiter_id = ( SELECT auth.uid() AS uid)) AND (a.status = ANY (ARRAY['applied'::text, 'reviewing'::text, 'shortlisted'::text, 'interviewing'::text, 'offered'::text, 'hired'::text]))))));\nCREATE POLICY candidate_profiles_self_and_admin_select ON candidate_profiles FOR SELECT TO public USING (((id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1\n   FROM profiles p\n  WHERE ((p.id = ( SELECT auth.uid() AS uid)) AND ((p.role = 'admin'::text) OR (p.role = 'super_admin'::text)))))));\nCREATE POLICY candidate_profiles_update ON candidate_profiles FOR UPDATE TO public USING ((id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON candidate_profiles FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Triggers for table: candidate_profiles\nCREATE TRIGGER tr_candidate_update BEFORE UPDATE ON candidate_profiles FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER trigger_check_primary_resume_ownership BEFORE INSERT ON candidate_profiles FOR EACH ROW EXECUTE FUNCTION check_primary_resume_ownership();\nCREATE TRIGGER trigger_check_primary_resume_ownership BEFORE UPDATE ON candidate_profiles FOR EACH ROW EXECUTE FUNCTION check_primary_resume_ownership();\nCREATE TRIGGER trigger_set_updated_at BEFORE UPDATE ON candidate_profiles FOR EACH ROW EXECUTE FUNCTION set_current_timestamp_updated_at();\nCREATE TRIGGER trigger_sync_profile_strength AFTER INSERT ON candidate_profiles FOR EACH ROW EXECUTE FUNCTION sync_profile_strength();\nCREATE TRIGGER trigger_sync_profile_strength AFTER UPDATE ON candidate_profiles FOR EACH ROW EXECUTE FUNCTION sync_profile_strength();\nCREATE TRIGGER update_candidate_profiles_updated_at BEFORE UPDATE ON candidate_profiles FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n\n-- Data for table: candidate_profiles\nINSERT INTO candidate_profiles (id, headline, skills, experience_years, education, work_history, resume_url, linkedin_url, github_url, portfolio_url, salary_min, salary_max, currency, job_types, preferred_locations, open_to_remote, profile_strength, is_visible, updated_at, resume_path, primary_resume_id, is_discoverable) VALUES ('c10f6c00-97ab-4376-b8d3-8164e9d3c8d2', NULL, '[\"React\",\"Node.js\",\"TypeScript\"]', 0, '[]', '[]', NULL, NULL, NULL, NULL, NULL, NULL, 'INR', NULL, NULL, true, 0, true, '2026-06-13T11:22:50.813Z', NULL, NULL, true);\nINSERT INTO candidate_profiles (id, headline, skills, experience_years, education, work_history, resume_url, linkedin_url, github_url, portfolio_url, salary_min, salary_max, currency, job_types, preferred_locations, open_to_remote, profile_strength, is_visible, updated_at, resume_path, primary_resume_id, is_discoverable) VALUES ('18d329f1-7301-4359-91b4-595f948f4342', 'Lead QA Engineer', '[\"Zod\",\"Jest\",\"Playwright\"]', 0, '[]', '[{\"id\":\