 public.candidate_resumes USING btree (candidate_id);\n\n-- Foreign key constraints for table: candidate_resumes\nALTER TABLE candidate_resumes ADD CONSTRAINT candidate_resumes_candidate_id_fkey FOREIGN KEY (candidate_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: candidate_resumes\nALTER TABLE candidate_resumes ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: candidate_resumes\nCREATE POLICY \"Candidates can manage own resumes\" ON candidate_resumes FOR ALL TO public USING ((candidate_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY admin_bypass ON candidate_resumes FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY candidate_resumes_delete ON candidate_resumes FOR DELETE TO public USING ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY candidate_resumes_insert ON candidate_resumes FOR INSERT TO public WITH CHECK ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY candidate_resumes_recruiter_select ON candidate_resumes FOR SELECT TO public USING ((EXISTS ( SELECT 1\n   FROM (applications a\n     JOIN jobs j ON ((j.id = a.job_id)))\n  WHERE ((a.candidate_id = candidate_resumes.candidate_id) AND (j.recruiter_id = ( SELECT auth.uid() AS uid)) AND (a.status = ANY (ARRAY['applied'::text, 'reviewing'::text, 'shortlisted'::text, 'interviewing'::text, 'offered'::text, 'hired'::text]))))));\nCREATE POLICY candidate_resumes_select_admin ON candidate_resumes FOR SELECT TO authenticated USING (is_admin());\nCREATE POLICY candidate_resumes_select_self ON candidate_resumes FOR SELECT TO authenticated USING ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY candidate_resumes_update ON candidate_resumes FOR UPDATE TO public USING ((candidate_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON candidate_resumes FOR ALL TO project_admin USING (true) W