_at();\n\n-- Table: custom_proposals\nCREATE TABLE IF NOT EXISTS custom_proposals (id uuid NOT NULL DEFAULT gen_random_uuid(), recruiter_id uuid, features jsonb NOT NULL, price numeric NOT NULL, status text DEFAULT 'pending'::text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());\n\n-- Indexes for table: custom_proposals\nCREATE INDEX idx_custom_proposals_recruiter_id ON public.custom_proposals USING btree (recruiter_id);\n\n-- Foreign key constraints for table: custom_proposals\nALTER TABLE custom_proposals ADD CONSTRAINT custom_proposals_recruiter_id_fkey FOREIGN KEY (recruiter_id) REFERENCES profiles (id);\n\n-- RLS enabled for table: custom_proposals\nALTER TABLE custom_proposals ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: custom_proposals\nCREATE POLICY admin_bypass_proposals ON custom_proposals FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON custom_proposals FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY proposals_select_own ON custom_proposals FOR SELECT TO public USING ((( SELECT auth.uid() AS uid) = recruiter_id));\n\n-- Table: debug_output\nCREATE TABLE IF NOT EXISTS debug_output (val text);\n\n-- RLS enabled for table: debug_output\nALTER TABLE debug_output ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: debug_output\nCREATE POLICY project_admin_policy ON debug_output FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Data for table: debug_output\nINSERT INTO debug_output (val) VALUES ('[{\"schemaname\":\"public\",\"tablename\":\"applications\",\"policyname\":\"applications_self\",\"cmd\":\"SELECT\"}, \n {\"schemaname\":\"public\",\"tablename\":\"applications\",\"policyname\":\"applications_insert_candidate\",\"cmd\":\"INSERT\"}, \n {\"schemaname\":\"public\",\"tablename\":\"jobs\",\"policyname\":\"jobs_select_approved\",\"cmd\":\"SELECT\"}, \n {\"schemaname\":\"public\",\"tablename\":\"jobs\",\"policyname\":\"jobs_select_