{\"schemaname\":\"public\",\"tablename\":\"jobs\",\"policyname\":\"admins_all\",\"cmd\":\"ALL\"}, \n {\"schemaname\":\"public\",\"tablename\":\"jobs\",\"policyname\":\"project_admin_policy\",\"cmd\":\"ALL\"}, \n {\"schemaname\":\"public\",\"tablename\":\"jobs\",\"policyname\":\"public_select\",\"cmd\":\"SELECT\"}, \n {\"schemaname\":\"public\",\"tablename\":\"applications\",\"policyname\":\"apps_recruiter_view\",\"cmd\":\"SELECT\"}, \n {\"schemaname\":\"public\",\"tablename\":\"applications\",\"policyname\":\"apps_recruiter_update\",\"cmd\":\"UPDATE\"}, \n {\"schemaname\":\"public\",\"tablename\":\"jobs\",\"policyname\":\"jobs_update_unapproved\",\"cmd\":\"UPDATE\"}, \n {\"schemaname\":\"public\",\"tablename\":\"jobs\",\"policyname\":\"jobs_update_approved\",\"cmd\":\"UPDATE\"}, \n {\"schemaname\":\"public\",\"tablename\":\"profiles\",\"policyname\":\"Admins can manage profiles\",\"cmd\":\"ALL\"}, \n {\"schemaname\":\"public\",\"tablename\":\"profiles\",\"policyname\":\"admin_bypass_profiles\",\"cmd\":\"ALL\"}, \n {\"schemaname\":\"public\",\"tablename\":\"profiles\",\"policyname\":\"profiles_select_self\",\"cmd\":\"SELECT\"}, \n {\"schemaname\":\"public\",\"tablename\":\"profiles\",\"policyname\":\"profiles_select_admin\",\"cmd\":\"SELECT\"}, \n {\"schemaname\":\"public\",\"tablename\":\"profiles\",\"policyname\":\"profiles_recruiter_select\",\"cmd\":\"SELECT\"}, \n {\"schemaname\":\"public\",\"tablename\":\"jobs\",\"policyname\":\"admin_bypass\",\"cmd\":\"ALL\"}, \n {\"schemaname\":\"public\",\"tablename\":\"applications\",\"policyname\":\"admin_bypass\",\"cmd\":\"ALL\"}, \n {\"schemaname\":\"public\",\"tablename\":\"profiles\",\"policyname\":\"profiles_self\",\"cmd\":\"ALL\"}]');\nINSERT INTO debug_output (val) VALUES ('[{\"def\":\"CREATE OR REPLACE FUNCTION public.is_admin()\\n RETURNS boolean\\n LANGUAGE plpgsql\\n SECURITY DEFINER\\n SET search_path TO ''public''\\nAS $function$\\nDECLARE\\n  is_adm BOOLEAN;\\nBEGIN\\n  IF auth.uid() IS NULL THEN\\n    RETURN FALSE;\\n  END IF;\\n  \\n  -- Querying admin_users never triggers RLS as RLS is disabled on it\\n  SELECT EXISTS (\\n    SELECT 1 FROM public.admin_users WHERE user_id = auth.uid()\\n  ) INTO is_adm;\\n  \\n  RETURN is_adm;\\nEND;\\n$function$\\n\"}]');\nINSERT INTO debug_output (val) VALUES ('[{\"admin_count\":7}]');\n\n-- Table: export_candidates\nCREATE TABLE IF NOT EXISTS export_candidates (id uuid NOT NULL DEFAULT gen_random_uuid(), job_id uuid, candidate_id uuid, created_at timestamptz DEFAULT now());\n\n-- Indexes for table: export_candidates\nCREATE INDEX idx_export_candidates_candidate_id ON public.export_candidates USING btree (candidate_id);\nCREATE INDEX idx_export_candidates_job_id ON public.export_candidates USING btree (job_id);\n\n-- Foreign key constraints for table: export_candidates\nALTER TABLE export_candidates ADD CONSTRAINT export_candidates_candidate_id_fkey FOREIGN KEY (candidate_id) REFERENCES profiles (id) ON DELETE CASCADE;\nALTER TABLE export_candidates ADD CONSTRAINT export_candidates_job_id_fkey FOREIGN KEY (job_id) REFERENCES export_jobs (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: export_candidates\nALTER TABLE export_candidates ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: export_candidates\nCREATE POLICY \"Admins can do everything on export candidates\" ON export_candidates FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY \"Users can view own export candidates\" ON export_candidates FOR SELECT TO public USING ((EXISTS ( SELECT 1\n   FROM export_jobs\n  WHERE ((export_jobs.id = export_candidates.job_id) AND (export_jobs.user_id = ( SELECT auth.uid() AS uid))))));\nCREATE POLICY project_admin_policy ON export_candidates FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: export_jobs\nCREATE TABLE IF NOT EXISTS export_jobs (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, status text NOT NULL DEFAULT 'pending'::text, type text NOT NULL, filters jsonb DEFAULT '{}'::jsonb, download_url text, error_message text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());\n\n-- Indexes for table: export_jobs\nCREATE INDEX idx_export_jobs_user_id ON public.export_jobs USING btree (user_id);\n\n-- Foreign key constraints for table: export_jobs\nALTER TABLE export_jobs ADD CONSTRAINT export_jobs_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: export_jobs\nALTER TABLE export_jobs ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: export_jobs\nCREATE POLICY \"Admins can do everything on export jobs\" ON export_jobs FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY \"Users can insert own export jobs\" ON export_jobs FOR INSERT TO public WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Users can update own export jobs\" ON export_jobs FOR UPDATE TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Users can view own export jobs\" ON export_jobs FOR SELECT TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON export_jobs FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: idempotency_keys\nCREATE TABLE IF NOT EXISTS idempotency_keys (key text NOT NULL, status integer NOT NULL, response_hash text NOT NULL, response_ref uuid, created_at timestamptz DEFAULT now(), expires_at timestamptz DEFAULT (now() + '24:00:00'::interval));\n\n-- RLS enabled for table: idempotency_keys\nALTER TABLE idempotency_keys ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: idempotency_keys\nCREATE POLICY \"Admins can do everything on idempotency keys\" ON idempotency_keys FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON idempotency_keys FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: interviews\nCREATE TABLE IF NOT EXISTS interviews (id uuid NOT NULL DEFAULT gen_random_uuid(), application_id uuid NOT NULL, recruiter_id uuid NOT NULL, candidate_id uuid NOT NULL, type text, status text DEFAULT 'scheduled'::text, scheduled_at timestamptz NOT NULL, duration_mins integer DEFAULT 45, meeting_link text, google_event_id text, feedback text, rating integer, created_at timestamptz DEFAULT now(), job_id uuid);\n\n-- Indexes for table: interviews\nCREATE INDEX idx_interviews_application_id ON public.interviews USING btree (application_id);\nCREATE INDEX idx_interviews_candidate_id ON public.interviews USING btree (candidate_id);\nCREATE INDEX idx_interviews_job_id ON public.interviews USING btree (job_id);\nCREATE INDEX idx_interviews_recruiter_id ON public.interviews USING btree (recruiter_id);\n\n-- Foreign key constraints for table: interviews\nALTER TABLE interviews ADD CONSTRAINT interviews_application_id_fkey FOREIGN KEY (application_id) REFERENCES applications (id);\nALTER TABLE interviews ADD CONSTRAINT interviews_candidate_id_fkey FOREIGN KEY (candidate_id) REFERENCES profiles (id) ON DELETE CASCADE;\nALTER TABLE interviews ADD CONSTRAINT interviews_job_id_fkey FOREIGN KEY (job_id) REFERENCES jobs (id) ON DELETE SET NULL;\nALTER TABLE interviews ADD CONSTRAINT interviews_recruiter_id_fkey FOREIGN KEY (recruiter_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: interviews\nALTER TABLE interviews ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: interviews\nCREATE POLICY \"Interviews access\" ON interviews FOR SELECT TO public USING (((candidate_id = ( SELECT auth.uid() AS uid)) OR (recruiter_id = ( SELECT auth.uid() AS uid))));\nCREATE POLICY \"Recruiter manage interviews\" ON interviews FOR INSERT TO public WITH CHECK ((recruiter_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Recruiter update interviews\" ON interviews FOR UPDATE TO public USING ((recruiter_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON interviews FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: job_alerts\nCREATE TABLE IF NOT EXISTS job_alerts (id uuid NOT NULL DEFAULT gen_random_uuid(), candidate_id uuid, alert_name text, search_query_json jsonb, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());\n\n-- Indexes for table: job_alerts\nCREATE INDEX idx_job_alerts_candidate_id ON public.job_alerts USING btree (candidate_id);\n\n-- Foreign key constraints for table: job_alerts\nALTER TABLE job_alerts ADD CONSTRAINT job_alerts_candidate_id_fkey FOREIGN KEY (candidate_id) REFERENCES profiles (id);\n\n-- RLS enabled for table: job_alerts\nALTER TABLE job_alerts ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: job_alerts\nCREATE POLICY admin_bypass ON job_alerts FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY job_alerts_self ON job_alerts FOR ALL TO public USING ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON job_alerts FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: jobs\nCREATE TABLE IF NOT EXISTS jobs (id uuid NOT NULL DEFAULT gen_random_uuid(), company_id uuid NOT NULL, recruiter_id uuid NOT NULL, title text NOT NULL, description text NOT NULL, requirements ARRAY, skills_required ARRAY, type text, location text, salary_min numeric, salary_max numeric, currency text DEFAULT 'INR'::text, experience_min integer DEFAULT 0, experience_max integer, department text, status text DEFAULT 'draft'::text, is_approved boolean DEFAULT false, views_count integer DEFAULT 0, applications_count integer DEFAULT 0, fts tsvector, expires_at timestamptz, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());\n\n-- Indexes for table: jobs\nCREATE INDEX idx_jobs_company ON public.jobs USING btree (company_id);\nCREATE INDEX idx_jobs_fts ON public.jobs USING gin (fts);\nCREATE INDEX idx_jobs_recruiter_id ON public.jobs USING btree (recruiter_id);\nCREATE INDEX idx_jobs_status ON public.jobs USING btree (status, is_approved);\nCREATE INDEX idx_jobs_status_approved ON public.jobs USING btree (status, is_approved);\n\n-- Foreign key constraints for table: jobs\nALTER TABLE jobs ADD CONSTRAINT jobs_company_id_fkey FOREIGN KEY (company_id) REFERENCES companies (id);\n\n-- RLS enabled for table: jobs\nALTER TABLE jobs ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: jobs\nCREATE POLICY \"Admins can view all jobs\" ON jobs FOR SELECT TO authenticated USING (is_admin());\nCREATE POLICY \"Recruiters can delete own jobs\" ON jobs FOR DELETE TO public USING ((( SELECT auth.uid() AS uid) = recruiter_id));\nCREATE POLICY \"Recruiters can insert jobs\" ON jobs FOR INSERT TO public WITH CHECK (((( SELECT auth.uid() AS uid) = recruiter_id) AND is_recruiter()));\nCREATE POLICY \"Recruiters can update own jobs\" ON jobs FOR UPDATE TO public USING ((( SELECT auth.uid() AS uid) = recruiter_id));\nCREATE POLICY \"Recruiters view own jobs\" ON jobs FOR SELECT TO public USING ((( SELECT auth.uid() AS uid) = recruiter_id));\nCREATE POLICY admin_bypass ON jobs FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY admins_all ON jobs FOR ALL TO authenticated USING (is_admin()) WITH CHECK (is_admin());\nCREATE POLICY jobs_delete_own ON jobs FOR DELETE TO public USING ((( SELECT auth.uid() AS uid) = recruiter_id));\nCREATE POLICY jobs_insert_own ON jobs FOR INSERT TO public WITH CHECK ((( SELECT auth.uid() AS uid) = recruiter_id));\nCREATE POLICY jobs_select_approved ON jobs FOR SELECT TO public USING (((status = 'active'::text) AND (is_approved = true)));\nCREATE POLICY jobs_select_own ON jobs FOR SELECT TO public USING ((( SELECT auth.uid() AS uid) = recruiter_id));\nCREATE POLICY jobs_update_approved ON jobs FOR UPDATE TO public USING (((( SELECT auth.uid() AS uid) = recruiter_id) AND (is_approved = true))) WITH CHECK ((( SELECT auth.uid() AS uid) = recruiter_id));\nCREATE POLICY jobs_update_own ON jobs FOR UPDATE TO public USING ((( SELECT auth.uid() AS uid) = recruiter_id));\nCREATE POLICY jobs_update_unapproved ON jobs FOR UPDATE TO public USING (((( SELECT auth.uid() AS uid) = recruiter_id) AND (is_approved = false))) WITH CHECK (((( SELECT auth.uid() AS uid) = recruiter_id) AND (is_approved = false)));\nCREATE POLICY project_admin_policy ON jobs FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY public_select ON jobs FOR SELECT TO public USING (((status = 'active'::text) AND (is_approved = true)));\n\n-- Triggers for table: jobs\nCREATE TRIGGER tr_jobs_update BEFORE UPDATE ON jobs FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER trigger_set_updated_at BEFORE UPDATE ON jobs FOR EACH ROW EXECUTE FUNCTION set_current_timestamp_updated_at();\nCREATE TRIGGER update_jobs_updated_at BEFORE UPDATE ON jobs FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n\n-- Data for table: jobs\nINSERT INTO jobs (id, company_id, recruiter_id, title, description, requirements, skills_required, type, location, salary_min, salary_max, currency, experience_min, experience_max, department, status, is_approved, views_count, applications_count, fts, expires_at, created_at, updated_at) VALUES ('0033875b-bd44-482c-a1d9-41aeb54c36f2', '8773045c-c46c-4834-9efd-3226e00e5833', '59b913d9-bfbb-4e3d-b0c3-67099533d50b', 'Devops Engineer', 'jobs descriptions are here so candidates can watch and the apply process are easy', '[\"5+ years of experience\"]', '[\"typescript, javascript\"]', 'full-time', 'India', '45000', '50000', 'INR', 1, 3, 'Engineering', 'active', true, 0, 4, '''appli'':13 ''candid'':8 ''descript'':4 ''devop'':1 ''easi'':16 ''engin'':2 ''job'':3 ''process'':14 ''watch'':10', NULL, '2026-03-28T12:47:49.467Z', '2026-07-08T10:52:52.419Z');\nINSERT INTO jobs (id, company_id, recruiter_id, title, description, requirements, skills_required, type, location, salary_min, salary_max, currency, experience_min, experience_max, department, status, is_approved, views_count, applications_count, fts, expires_at, created_at, updated_at) VALUES ('a21df5b6-30d6-47d4-8d40-f451f38caf29', '8773045c-c46c-4834-9efd-3226e00e5833', '59b913d9-bfbb-4e3d-b0c3-67099533d50b', 'Data analysts ', 'Collect, clean, and analyze data to generate insights. Build dashboards, reports, and visualizations. Use tools like SQL, Excel, and Python. Identify trends, support decision-making, and communicate findings to stakeholders for business improvement.\n', '[\"Bachelor’s degree in IT, Statistics, or related field. Strong skills in SQL, Excel, and data visualization tools (Power BI/Tableau). Basic knowledge of Python/R preferred. Analytical thinking, problem-solving ability, and good communication skills. Experience with data cleaning and reporting is a plus.\"]', '[\"React.js\"]', 'remote', 'modasa', '20000', '50000', 'INR', 1, 2, 'it sector', 'active', true, 0, 28, '''analyst'':2 ''analyz'':6 ''build'':11 ''busi'':35 ''clean'':4 ''collect'':3 ''communic'':30 ''dashboard'':12 ''data'':1,7 ''decis'':27 ''decision-mak'':26 ''excel'':20 ''find'':31 ''generat'':9 ''identifi'':23 ''improv'':36 ''insight'':10 ''like'':18 ''make'':28 ''python'':22 ''report'':13 ''sql'':19 ''stakehold'':33 ''support'':25 ''tool'':17 ''trend'':24 ''use'':16 ''visual'':15', NULL, '2026-04-04T13:03:58.954Z', '2026-07-08T10:52:52.577Z');\n\n-- Table: live_ai_interviews\nCREATE TABLE IF NOT EXISTS live_ai_interviews (id uuid NOT NULL DEFAULT gen_random_uuid(), role text NOT NULL, questions jsonb NOT NULL DEFAULT '[]'::jsonb, conversation jsonb NOT NULL DEFAULT '[]'::jsonb, evaluation jsonb, status text NOT NULL DEFAULT 'pending'::text, created_at timestamptz DEFAULT now(), completed_at timestamptz, candidate_id uuid);\n\n-- Indexes for table: live_ai_interviews\nCREATE INDEX idx_live_ai_interviews_candidate_id ON public.live_ai_interviews USING btree (candidate_id);\nCREATE INDEX idx_live_ai_interviews_created_at ON public.live_ai_interviews USING btree (created_at DESC);\nCREATE INDEX idx_live_ai_interviews_status ON public.live_ai_interviews USING btree (status);\n\n-- Foreign key constraints for table: live_ai_interviews\nALTER TABLE live_ai_interviews ADD CONSTRAINT live_ai_interviews_candidate_id_fkey FOREIGN KEY (candidate_id) REFERENCES profiles (id);\n\n-- RLS enabled for table: live_ai_interviews\nALTER TABLE live_ai_interviews ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: live_ai_interviews\nCREATE POLICY \"Candidates insert own live interviews\" ON live_ai_interviews FOR INSERT TO authenticated WITH CHECK ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Candidates see own live interviews\" ON live_ai_interviews FOR SELECT TO authenticated USING ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Super admin sees all live interviews\" ON live_ai_interviews FOR ALL TO authenticated USING ((( SELECT profiles.role\n   FROM profiles\n  WHERE (profiles.id = ( SELECT auth.uid() AS uid))) = 'super_admin'::text));\nCREATE POLICY project_admin_policy ON live_ai_interviews FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: messages\nCREATE TABLE IF NOT EXISTS messages (id uuid NOT NULL DEFAULT gen_random_uuid(), sender_id uuid NOT NULL, receiver_id uuid NOT NULL, job_id uuid, content text NOT NULL, is_read boolean DEFAULT false, created_at timestamptz DEFAULT now());\n\n-- Indexes for table: messages\nCREATE INDEX idx_messages_job_id ON public.messages USING btree (job_id);\nCREATE INDEX idx_messages_receiver ON public.messages USING btree (receiver_id, created_at DESC);\nCREATE INDEX idx_messages_sender ON public.messages USING btree (sender_id, created_at DESC);\n\n-- Foreign key constraints for table: messages\nALTER TABLE messages ADD CONSTRAINT messages_job_id_fkey FOREIGN KEY (job_id) REFERENCES jobs (id);\n\n-- RLS enabled for table: messages\nALTER TABLE messages ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: messages\nCREATE POLICY \"Messages access\" ON messages FOR ALL TO public USING (((sender_id = ( SELECT auth.uid() AS uid)) OR (receiver_id = ( SELECT auth.uid() AS uid))));\nCREATE POLICY project_admin_policy ON messages FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: newsletter_rate_limits\nCREATE TABLE IF NOT EXISTS newsletter_rate_limits (ip_hash text NOT NULL, request_count integer NOT NULL DEFAULT 1, window_start timestamptz NOT NULL DEFAULT now());\n\n-- Data for table: newsletter_rate_limits\nINSERT INTO newsletter_rate_limits (ip_hash, request_count, window_start) VALUES ('eff8e7ca506627fe15dda5e0e512fcaad70b6d520f37cc76597fdb4f2d83a1a3', 3, '2026-07-09T10:45:54.169Z');\n\n-- Table: newsletter_subscribers\nCREATE TABLE IF NOT EXISTS newsletter_subscribers (id uuid NOT NULL DEFAULT gen_random_uuid(), email text NOT NULL, status USER-DEFINED NOT NULL DEFAULT 'pending'::newsletter_status, source text NOT NULL DEFAULT 'footer'::text, interests ARRAY, confirmation_token_hash text, confirmation_token_expires_at timestamptz, confirmation_email_sent_at timestamptz, confirmed_at timestamptz, unsubscribe_token text NOT NULL, last_email_sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), user_agent text);\n\n-- Indexes for table: newsletter_subscribers\nCREATE INDEX idx_newsletter_created_at ON public.newsletter_subscribers USING btree (created_at);\nCREATE UNIQUE INDEX idx_newsletter_email ON public.newsletter_subscribers USING btree (email);\nCREATE INDEX idx_newsletter_status ON public.newsletter_subscribers USING btree (status);\nCREATE INDEX idx_newsletter_token_hash ON public.newsletter_subscribers USING btree (confirmation_token_hash) WHERE (confirmation_token_hash IS NOT NULL);\nCREATE UNIQUE INDEX idx_newsletter_unsub_token ON public.newsletter_subscribers USING btree (unsubscribe_token);\nCREATE UNIQUE INDEX newsletter_subscribers_email_key ON public.newsletter_subscribers USING btree (email);\nCREATE UNIQUE INDEX newsletter_subscribers_unsubscribe_token_key ON public.newsletter_subscribers USING btree (unsubscribe_token);\n\n-- Data for table: newsletter_subscribers\nINSERT INTO newsletter_subscribers (id, email, status, source, interests, confirmation_token_hash, confirmation_token_expires_at, confirmation_email_sent_at, confirmed_at, unsubscribe_token, last_email_sent_at, created_at, updated_at, user_agent) VALUES ('8dd5f33f-d70a-4dbb-b109-179add201899', 'test-newsletter@example.com', 'unsubscribed', 'footer', NULL, NULL, NULL, '2026-07-09T09:45:08.900Z', '2026-07-09T09:46:06.820Z', 'eac17743-0684-4e3f-9311-2d275b125d56', NULL, '2026-07-09T09:45:08.900Z', '2026-07-09T09:47:34.923Z', 'Mozilla/5.0 (Windows NT; Windows NT 10.0; en-IN) WindowsPowerShell/5.1.26100.8655');\nINSERT INTO newsletter_subscribers (id, email, status, source, interests, confirmation_token_hash, confirmation_token_expires_at, confirmation_email_sent_at, confirmed_at, unsubscribe_token, last_email_sent_at, created_at, updated_at, user_agent) VALUES ('919aa99a-822e-4d19-9549-7ae822c71893', 'anuj28122004@gmail.com', 'pending', 'footer', NULL, '4991e80de5139ad82662703421dfe014280690a44729ccd2d4eda6bb434efac5', '2026-07-10T10:51:39.586Z', '2026-07-09T10:51:39.587Z', NULL, '43139660-8ad6-4502-b99e-14d13bf34229', NULL, '2026-07-09T10:51:39.587Z', '2026-07-09T10:51:39.587Z', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36');\nINSERT INTO newsletter_subscribers (id, email, status, source, interests, confirmation_token_hash, confirmation_token_expires_at, confirmation_email_sent_at, confirmed_at, unsubscribe_token, last_email_sent_at, created_at, updated_at, user_agent) VALUES ('25444fa0-b1f1-428a-ba47-26da8a2fb3a5', 'anuj2812004@gmail.com', 'confirmed', 'footer', NULL, NULL, NULL, '2026-07-09T10:52:04.726Z', '2026-07-09T10:52:38.478Z', 'cae0d4be-0b86-47dd-977e-fdb139b5b672', NULL, '2026-07-09T10:52:04.726Z', '2026-07-09T10:52:38.478Z', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36');\n\n-- Table: notification_events\nCREATE TABLE IF NOT EXISTS notification_events (id uuid NOT NULL DEFAULT gen_random_uuid(), job_id uuid, event_type text NOT NULL, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz DEFAULT now());\n\n-- Indexes for table: notification_events\nCREATE INDEX idx_notification_events_job_id ON public.notification_events USING btree (job_id);\n\n-- Foreign key constraints for table: notification_events\nALTER TABLE notification_events ADD CONSTRAINT notification_events_job_id_fkey FOREIGN KEY (job_id) REFERENCES notification_jobs (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: notification_events\nALTER TABLE notification_events ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: notification_events\nCREATE POLICY events_all_admin ON notification_events FOR ALL TO public USING ((EXISTS ( SELECT 1\n   FROM profiles p\n  WHERE ((p.id = ( SELECT auth.uid() AS uid)) AND ((p.role = 'admin'::text) OR (p.role = 'super_admin'::text))))));\nCREATE POLICY events_select_recipient ON notification_events FOR SELECT TO public USING ((EXISTS ( SELECT 1\n   FROM notification_jobs j\n  WHERE ((j.id = notification_events.job_id) AND (j.user_id = ( SELECT auth.uid() AS uid))))));\nCREATE POLICY project_admin_policy ON notification_events FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: notification_jobs\nCREATE TABLE IF NOT EXISTS notification_jobs (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, template_id uuid, channel text NOT NULL, status text NOT NULL DEFAULT 'pending'::text, priority text NOT NULL DEFAULT 'normal'::text, title text NOT NULL, message text NOT NULL, payload jsonb DEFAULT '{}'::jsonb, dedupe_key text, retry_count integer DEFAULT 0, last_error text, locked_at timestamptz, locked_by text, lease_expires_at timestamptz, heartbeat_at timestamptz, next_attempt_at timestamptz, sent_at timestamptz, delivered_at timestamptz, expires_at timestamptz NOT NULL, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());\n\n-- Indexes for table: notification_jobs\nCREATE INDEX idx_notification_jobs_template_id ON public.notification_jobs USING btree (template_id);\nCREATE INDEX idx_notification_jobs_user_id ON public.notification_jobs USING btree (user_id);\nCREATE UNIQUE INDEX notification_jobs_dedupe_key_key ON public.notification_jobs USING btree (dedupe_key);\n\n-- Foreign key constraints for table: notification_jobs\nALTER TABLE notification_jobs ADD CONSTRAINT notification_jobs_template_id_fkey FOREIGN KEY (template_id) REFERENCES notification_templates (id) ON DELETE SET NULL;\nALTER TABLE notification_jobs ADD CONSTRAINT notification_jobs_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: notification_jobs\nALTER TABLE notification_jobs ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: notification_jobs\nCREATE POLICY jobs_all_admin ON notification_jobs FOR ALL TO public USING ((EXISTS ( SELECT 1\n   FROM profiles p\n  WHERE ((p.id = ( SELECT auth.uid() AS uid)) AND ((p.role = 'admin'::text) OR (p.role = 'super_admin'::text))))));\nCREATE POLICY jobs_select_recipient ON notification_jobs FOR SELECT TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON notification_jobs FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Triggers for table: notification_jobs\nCREATE TRIGGER notification_jobs_throttle_trigger BEFORE INSERT ON notification_jobs FOR EACH ROW EXECUTE FUNCTION check_notification_throttle();\n\n-- Table: notification_preferences\nCREATE TABLE IF NOT EXISTS notification_preferences (user_id uuid NOT NULL, email_enabled boolean DEFAULT true, push_enabled boolean DEFAULT true, digest_enabled boolean DEFAULT false, quiet_hours jsonb DEFAULT '{\"end\": \"08:00\", \"start\": \"22:00\", \"enabled\": false}'::jsonb, updated_at timestamptz DEFAULT now());\n\n-- Foreign key constraints for table: notification_preferences\nALTER TABLE notification_preferences ADD CONSTRAINT notification_preferences_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: notification_preferences\nALTER TABLE notification_preferences ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: notification_preferences\nCREATE POLICY prefs_all_admin ON notification_preferences FOR ALL TO public USING ((EXISTS ( SELECT 1\n   FROM profiles p\n  WHERE ((p.id = ( SELECT auth.uid() AS uid)) AND ((p.role = 'admin'::text) OR (p.role = 'super_admin'::text))))));\nCREATE POLICY prefs_select_update_recipient ON notification_preferences FOR ALL TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON notification_preferences FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Data for table: notification_preferences\nINSERT INTO notification_preferences (user_id, email_enabled, push_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('464fd40c-d5dd-4aca-8a8c-c1dad7a9149b', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-06-10T09:17:28.560Z');\nINSERT INTO notification_preferences (user_id, email_enabled, push_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('367bcef8-4e18-492d-838a-6cc93509db39', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-06-10T09:17:28.560Z');\nINSERT INTO notification_preferences (user_id, email_enabled, push_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('32fa6a29-3a0b-4b89-960c-597096f581a9', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-06-10T09:17:28.560Z');\nINSERT INTO notification_preferences (user_id, email_enabled, push_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('41af54da-6d2d-4ad2-a759-a60e29e7cc7a', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-06-10T09:17:28.560Z');\nINSERT INTO not