h_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('c36346b5-f761-4022-91b8-c773cc0cfbc3', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-06-17T14:41:22.525Z');\nINSERT INTO notification_preferences (user_id, email_enabled, push_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('aac5ac3c-7703-47a3-be94-3dc7752c7290', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-06-18T09:39:13.135Z');\nINSERT INTO notification_preferences (user_id, email_enabled, push_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('81fc7bdd-877a-49e6-a858-100cdf97bf16', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-06-18T09:55:57.642Z');\nINSERT INTO notification_preferences (user_id, email_enabled, push_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('32486494-87c7-465b-82fa-17eb876a9374', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-06-18T11:53:34.949Z');\nINSERT INTO notification_preferences (user_id, email_enabled, push_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('0141ed42-1a69-40a4-9125-4c6b8a0d5c22', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-06-18T12:06:04.160Z');\nINSERT INTO notification_preferences (user_id, email_enabled, push_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('20b164ec-827e-4a40-9d5d-0b16743f7771', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-06-18T12:36:55.469Z');\nINSERT INTO notification_preferences (user_id, email_enabled, push_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('b1067d26-5cfe-4f61-bcd8-b98734e8c258', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-06-24T10:24:35.541Z');\nINSERT INTO notification_preferences (user_id, email_enabled, push_enabled, digest_enabled, quiet_hours, updated_at) VALUES ('466abcc4-440f-4539-b13d-8c14cd07000c', true, true, false, '{\"end\":\"08:00\",\"start\":\"22:00\",\"enabled\":false}', '2026-07-07T11:30:34.729Z');\n\n-- Table: notification_receipts\nCREATE TABLE IF NOT EXISTS notification_receipts (id uuid NOT NULL DEFAULT gen_random_uuid(), notification_job_id uuid, user_id uuid, read_at timestamptz, clicked_at timestamptz, dismissed_at timestamptz, created_at timestamptz DEFAULT now());\n\n-- Indexes for table: notification_receipts\nCREATE INDEX idx_notification_receipts_notification_job_id ON public.notification_receipts USING btree (notification_job_id);\nCREATE INDEX idx_notification_receipts_user_id ON public.notification_receipts USING btree (user_id);\n\n-- Foreign key constraints for table: notification_receipts\nALTER TABLE notification_receipts ADD CONSTRAINT notification_receipts_notification_job_id_fkey FOREIGN KEY (notification_job_id) REFERENCES notification_jobs (id) ON DELETE CASCADE;\nALTER TABLE notification_receipts ADD CONSTRAINT notification_receipts_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: notification_receipts\nALTER TABLE notification_receipts ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: notification_receipts\nCREATE POLICY project_admin_policy ON notification_receipts FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY receipts_all_admin ON notification_receipts FOR ALL TO public USING ((EXISTS ( SELECT 1\n   FROM profiles p\n  WHERE ((p.id = ( SELECT auth.uid() AS uid)) AND ((p.role = 'admin'::text) OR (p.role = 'super_admin'::text))))));\nCREATE POLICY receipts_select_update_recipient ON notification_receipts FOR ALL TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\n\n-- Table: notification_templates\nCREATE TABLE IF NOT EXISTS notification_templates (id uuid NOT NULL DEFAULT gen_random_uuid(), key text NOT NULL, channels ARRAY DEFAULT ARRAY['in_app'::text, 'email'::text], title_template text NOT NULL, body_template text NOT NULL, allowed_variables ARRAY DEFAULT ARRAY[]::text[], created_at timestamptz DEFAULT now());\n\n-- Indexes for table: notification_templates\nCREATE UNIQUE INDEX notification_templates_key_key ON public.notification_templates USING btree (key);\n\n-- RLS enabled for table: notification_templates\nALTER TABLE notification_templates ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: notification_templates\nCREATE POLICY project_admin_policy ON notification_templates FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY templates_select_all ON notification_templates FOR SELECT TO public USING (true);\nCREATE POLICY templates_write_admin ON notification_templates FOR ALL TO public USING ((EXISTS ( SELECT 1\n   FROM profiles p\n  WHERE ((p.id = ( SELECT auth.uid() AS uid)) AND ((p.role = 'admin'::text) OR (p.role = 'super_admin'::text))))));\n\n-- Data for table: notification_templates\nINSERT INTO notification_templates (id, key, channels, title_template, body_template, allowed_variables, created_at) VALUES ('3c216375-a49f-4021-aeec-b3565d1b214f', 'application_update', '[\"in_app\",\"email\"]', 'Application Status Update: {{job}}', 'Hello {{candidate}}, your application status for {{job}} at {{company}} has been updated to {{status}}.', '[\"candidate\",\"job\",\"company\",\"status\"]', '2026-06-10T09:17:28.560Z');\nINSERT INTO notification_templates (id, key, channels, title_template, body_template, allowed_variables, created_at) VALUES ('e21e7d06-bff1-486b-844e-194137f8635c', 'interview_scheduled', '[\"in_app\",\"email\"]', 'Interview Scheduled: {{job}}', 'Hello {{candidate}}, your interview for {{job}} has been scheduled at {{time}}.', '[\"candidate\",\"job\",\"time\"]', '2026-06-10T09:17:28.560Z');\nINSERT INTO notification_templates (id, key, channels, title_template, body_template, allowed_variables, created_at) VALUES ('44f512cc-ffdf-4e7c-ba78-fba5cd931df2', 'security_alert', '[\"in_app\"]', 'Security Notice: New Login', 'We detected a new login on your account from IP {{ip_address}}.', '[\"ip_address\"]', '2026-06-10T09:17:28.560Z');\nINSERT INTO notification_templates (id, key, channels, title_template, body_template, allowed_variables, created_at) VALUES ('88ae5e31-f3ce-407a-8366-383f72101d98', 'export_ready', '[\"in_app\"]', 'Export Completed: {{export_type}}', 'Your CSV export for {{export_type}} is ready for download.', '[\"export_type\"]', '2026-06-10T09:17:28.560Z');\nINSERT INTO notification_templates (id, key, channels, title_template, body_template, allowed_variables, created_at) VALUES ('f3f03674-4364-498a-8b88-6138d8ed7890', 'test_notification', '[\"in_app\"]', 'Test Notification', 'This is a test notification containing variable {{test_val}}.', '[\"test_val\"]', '2026-06-10T09:17:28.560Z');\n\n-- Table: notifications\nCREATE TABLE IF NOT EXISTS notifications (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, type text NOT NULL, title text NOT NULL, message text, is_read boolean DEFAULT false, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamptz DEFAULT now());\n\n-- Indexes for table: notifications\nCREATE INDEX idx_notifications_user ON public.notifications USING btree (user_id, is_read, created_at DESC);\n\n-- RLS enabled for table: notifications\nALTER TABLE notifications ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: notifications\nCREATE POLICY \"Notifications access\" ON notifications FOR ALL TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY admin_bypass ON notifications FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY notifications_self_read ON notifications FOR SELECT TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY notifications_self_update ON notifications FOR UPDATE TO public USING ((user_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON notifications FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Triggers for table: notifications\nCREATE TRIGGER trigger_set_updated_at BEFORE UPDATE ON notifications FOR EACH ROW EXECUTE FUNCTION set_current_timestamp_updated_at();\n\n-- Data for table: notifications\nINSERT INTO notifications (id, user_id, type, title, message, is_read, metadata, created_at) VALUES ('6f96c699-730c-459a-bcb2-87c3b7eff476', 'cf11301b-50f8-41e7-8191-46713a735c4e', 'application_update', 'Application Status Update', 'Your application for \"Devops Engineer\" has been updated to: reviewing.', false, '{\"status\":\"reviewing\",\"job_title\":\"Devops Engineer\",\"application_id\":\"0f100e2e-8cba-4bdc-a394-473e1049df18\"}', '2026-06-08T10:14:04.060Z');\nINSERT INTO notifications (id, user_id, type, title, message, is_read, metadata, created_at) VALUES ('dc5cdd36-bf15-43c4-8562-c6afc9d39af8', '464fd40c-d5dd-4aca-8a8c-c1dad7a9149b', 'application_update', 'Application Status Update', 'Your application for \"Data analysts \" has been updated to: withdrawn.', false, '{\"status\":\"withdrawn\",\"job_title\":\"Data analysts \",\"application_id\":\"00000000-0000-0000-0000-000000000001\"}', '2026-06-12T08:54:46.338Z');\nINSERT INTO notifications (id, user_id, type, title, message, is_read, metadata, created_at) VALUES ('789409ce-d44b-44f9-b4f0-613600c2b870', '464fd40c-d5dd-4aca-8a8c-c1dad7a9149b', 'application_update', 'Application Status Update', 'Your application for \"Data analysts \" has been updated to: withdrawn.', false, '{\"status\":\"withdrawn\",\"job_title\":\"Data analysts \",\"application_id\":\"00000000-0000-0000-0000-000000000001\"}', '2026-06-12T08:59:14.930Z');\nINSERT INTO notifications (id, user_id, type, title, message, is_read, metadata, created_at) VALUES ('825617b8-ac8e-45e8-97a8-22bb85df6814', '464fd40c-d5dd-4aca-8a8c-c1dad7a9149b', 'application_update', 'Application Status Update', 'Your application for \"Data analysts \" has been updated to: withdrawn.', false, '{\"status\":\"withdrawn\",\"job_title\":