z, expires_at timestamptz DEFAULT (now() + '7 days'::interval), candidate_response text, candidate_reason text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());\n\n-- Indexes for table: nvites\nCREATE INDEX idx_nvites_candidate_id ON public.nvites USING btree (candidate_id);\nCREATE INDEX idx_nvites_job_id ON public.nvites USING btree (job_id);\nCREATE INDEX idx_nvites_recruiter_id ON public.nvites USING btree (recruiter_id);\n\n-- Foreign key constraints for table: nvites\nALTER TABLE nvites ADD CONSTRAINT nvites_candidate_id_fkey FOREIGN KEY (candidate_id) REFERENCES profiles (id) ON DELETE CASCADE;\nALTER TABLE nvites ADD CONSTRAINT nvites_job_id_fkey FOREIGN KEY (job_id) REFERENCES jobs (id) ON DELETE SET NULL;\nALTER TABLE nvites ADD CONSTRAINT nvites_recruiter_id_fkey FOREIGN KEY (recruiter_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: nvites\nALTER TABLE nvites ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: nvites\nCREATE POLICY admin_bypass ON nvites FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY nvites_insert_recruiter ON nvites FOR INSERT TO public WITH CHECK ((recruiter_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY nvites_select_candidate ON nvites FOR SELECT TO public USING ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY nvites_select_recruiter ON nvites FOR SELECT TO public USING ((recruiter_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY nvites_update_candidate ON nvites FOR UPDATE TO public USING ((candidate_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY nvites_update_recruiter ON nvites FOR UPDATE TO public USING ((recruiter_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((recruiter_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON nvites FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: offers\nCREATE TABLE IF NOT EXISTS offers (id uuid NOT NULL DEFAULT gen_random_uuid(), job_id uuid, candidate_id uuid, recruiter_id uuid, position_title text NOT NULL, salary_offered numeric NOT NULL, salary_currency text DEFAULT 'INR'::text, joining_date timestamptz NOT NULL, offer_valid_until timestamptz NOT NULL, work_mode text DEFAULT 'Remote'::text, work_location text, status text DEFAULT 'draft'::text, perks ARRAY DEFAULT '{}'::text[], responded_at timestamptz, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());\n\n-- Indexes for table: offers\nCREATE INDEX idx_offers_candidate_id ON public.offers USING btree (candidate_id);\nCREATE INDEX idx_offers_job_id ON public.offers USING btree (job_id);\nCREATE INDEX idx_offers_recruiter_id ON public.offers USING btree (recruiter_id);\n\n-- Foreign key constraints for table: offers\nALTER TABLE offers ADD CONSTRAINT offers_candidate_id_fkey FOREIGN KEY (candidate_id) REFERENCES profiles (id) ON DELETE CASCADE;\nALTER TABLE offers ADD CONSTRAINT offers_job_id_fkey FOREIGN KEY (job_id) REFERENCES jobs (id) ON DELETE SET NULL;\nALTER TABLE offers ADD CONSTRAINT offers_recruiter_id_fkey FOREIGN KEY (recruiter_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: offers\nALTER TABLE offers ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: offers\nCREATE POLICY offers_insert_recruiter ON offers FOR INSERT TO public WITH CHECK ((recruiter_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY offers_select_candidate ON offers FOR SELECT TO public USING ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY offers_select_recruiter ON offers FOR SELECT TO public USING ((recruiter_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY offers_update_candidate ON offers FOR UPDATE TO public USING ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY offers_update_recruiter ON offers FOR UPDATE TO public USING ((recruiter_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON offers FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: platform_settings\nCREATE TABLE IF NOT EXISTS platform_settings (key text NOT NULL, value jsonb NOT NULL, updated_at timestamptz DEFAULT now());\n\n-- RLS enabled for table: platform_settings\nALTER TABLE platform_settings ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: platform_settings\nCREATE POLICY \"Admins can manage platform_settings\" ON platform_settings FOR ALL TO public USING (is_admin()) WITH CHECK (is_admin());\nCREATE POLICY \"Anyone can read platform_settings\" ON platform_settings FOR SELECT TO public USING (true);\nCREATE POLICY admin_bypass_platform_settings ON platform_settings FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON platform_settings FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Data for table: platform_settings\nINSERT INTO platform_settings (key, value, updated_at) VALUES ('general', '{\"tagline\":\"The Future of Professional Integration\",\"platformName\":\"TalentMesh\",\"supportEmail\":\"support@talentmesh.ai\"}', '2026-06-08T05:20:00.903Z');\nINSERT INTO platform_settings (key, value, updated_at) VALUES ('maintenance', '{\"enabled\":false}', '2026-06-08T05:20:00.903Z');\nINSERT INTO platform_settings (key, value, updated_at) VALUES ('session_policy', '{\"admin\":{\"idleMs\":1800000,\"warningMs\":90000},\"candidate\":{\"idleMs\":5400000,\"warningMs\":90000},\"recruiter\":{\"idleMs\":5400000,\"warningMs\":90000}}', '2026-06-10T12:32:15.029Z');\nINSERT INTO platform_settings (key, value, updated_at) VALUES ('feature_flags', '{\"aiMatching\":true,\"blogEnabled\":true,\"messagingEnabled\":true,\"candidateRegistration\":false,\"recruiterRegistration\":true}', '2026-06-17T14:53:03.602Z');\n\n-- Table: profiles\nCREATE TABLE IF NOT EXISTS profiles (id uuid NOT NULL, email text, role text, name text, created_at timestamp without time zone DEFAULT now(), company_id uuid, avatar_url text, phone text, location text, bio text, is_active boolean DEFAULT true, updated_at timestamptz DEFAULT now(), mfa_enabled boolean DEFAULT false, mfa_secret text, last_login_at timestamptz, last_login_ip inet, login_count integer DEFAULT 0, password_set_at timestamptz, invited_by uuid, role_id text, completed_onboarding boolean DEFAULT false, status text DEFAULT 'pending'::text);\n\n-- Indexes for table: profiles\nCREATE INDEX idx_profiles_invited_by ON public.profiles USING btree (invited_by);\n\n-- Foreign key constraints for table: profiles\nALTER TABLE profiles ADD CONSTRAINT profiles_invited_by_fkey FOREIGN KEY (invited_by) REFERENCES profiles (id);\n\n-- RLS enabled for table: profiles\nALTER TABLE profiles ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: profiles\nCREATE POLICY \"Admins can manage profiles\" ON profiles FOR ALL TO public USING (is_admin());\nCREATE POLICY admin_bypass_profiles ON profiles FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY profiles_recruiter_select ON profiles FOR SELECT TO public USING ((EXISTS ( SELECT 1\n   FROM (applications a\n     JOIN jobs j ON ((j.id = a.job_id)))\n  WHERE ((a.candidate_id = profiles.id) AND (j.recruiter_id = ( SELECT auth.uid() AS uid)) AND (a.status = ANY (ARRAY['applied'::text, 'reviewing'::text, 'shortlisted'::text, 'interviewing'::text, 'offered'::text, 'hired'::text]))))));\nCREATE POLICY profiles_select_admin ON profiles FOR SELECT TO authenticated USING (is_admin());\nCREATE POLICY profiles_select_self ON profiles FOR SELECT TO authenticated USING ((id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY profiles_self ON profiles FOR ALL TO public USING ((id = ( SELECT auth.uid() AS uid))) WITH CHECK ((id = ( SELECT auth.uid() AS uid)));\n\n-- Triggers for table: profiles\nCREATE TRIGGER on_profile_created_prefs AFTER INSERT ON profiles FOR EACH ROW EXECUTE FUNCTION handle_new_profile_prefs();\nCREATE TRIGGER tr_profiles_update BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER trg_handle_password_change_invalidation AFTER UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION handle_password_change_invalidation();\nCREATE TRIGGER trg_sync_admin_users AFTER INSERT ON profiles FOR EACH ROW EXECUTE FUNCTION sync_admin_users();\nCREATE TRIGGER trg_sync_admin_users AFTER DELETE ON profiles FOR EACH ROW EXECUTE FUNCTION sync_admin_users();\nCREATE TRIGGER trg_sync_admin_users AFTER UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION sync_admin_users();\nCREATE TRIGGER trg_sync_recruiter_users AFTER INSERT ON profiles FOR EACH ROW EXECUTE FUNCTION sync_recruiter_users();\nCREATE TRIGGER trg_sync_recruiter_users AFTER DELETE ON profiles FOR EACH ROW EXECUTE FUNCTION sync_recruiter_users();\nCREATE TRIGGER trg_sync_recruiter_users AFTER UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION sync_recruiter_users();\nCREATE TRIGGER trigger_set_updated_at BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION set_current_timestamp_updated_at();\nCREATE TRIGGER trigger_sync_profile_strength AFTER INSERT ON profiles FOR EACH ROW EXECUTE FUNCTION sync_profile_strength();\nCREATE TRIGGER trigger_sync_profile_strength AFTER UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION sync_profile_strength();\nCREATE TRIGGER update_profiles_updated_at BEFORE UPDATE ON profiles FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n\n-- Data for table: profiles\nINSERT INTO profiles (id, email, role, name, created_at, company_id, avatar_url, phone, location, bio, is_active, updated_at, mfa_enabled, mfa_secret, last_login_at, last_login_ip, login_count, password_set_at, invited_by, role_id, completed_onboarding, status) VALUES ('464fd40c-d5dd-4aca-8a8c-c1dad7a9149b', 'manyamanya173@gmail.com', 'candidate', 'manyamanya173', '2026-04-06T07:12:39.269Z', NULL, NULL, '7016774410', 'AHMDABAD', NULL, true, '2026-04-29T05:49:48.628Z', false, NULL, NULL, NULL, 0, NULL, NULL, NULL, true, 'approved');\nINSERT INTO profiles (id, email, role, name, created_at, com