id uuid NOT NULL, candidate_id uuid NOT NULL, notes text NOT NULL, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());\n\n-- Indexes for table: recruiter_candidate_notes\nCREATE INDEX idx_recruiter_candidate_notes_candidate_id ON public.recruiter_candidate_notes USING btree (candidate_id);\nCREATE UNIQUE INDEX recruiter_candidate_notes_recruiter_id_candidate_id_key ON public.recruiter_candidate_notes USING btree (recruiter_id, candidate_id);\n\n-- Foreign key constraints for table: recruiter_candidate_notes\nALTER TABLE recruiter_candidate_notes ADD CONSTRAINT recruiter_candidate_notes_candidate_id_fkey FOREIGN KEY (candidate_id) REFERENCES profiles (id) ON DELETE CASCADE;\nALTER TABLE recruiter_candidate_notes ADD CONSTRAINT recruiter_candidate_notes_recruiter_id_fkey FOREIGN KEY (recruiter_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: recruiter_candidate_notes\nALTER TABLE recruiter_candidate_notes ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: recruiter_candidate_notes\nCREATE POLICY \"Admins can manage recruiter candidate notes\" ON recruiter_candidate_notes FOR ALL TO public USING (is_admin());\nCREATE POLICY \"Recruiters can manage own candidate notes\" ON recruiter_candidate_notes FOR ALL TO public USING ((recruiter_id = ( SELECT auth.uid() AS uid))) WITH CHECK ((recruiter_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON recruiter_candidate_notes FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: recruiter_profiles\nCREATE TABLE IF NOT EXISTS recruiter_profiles (id uuid NOT NULL, company_id uuid, job_title text, department text, is_approved boolean DEFAULT false, approved_by uuid, approved_at timestamptz, updated_at timestamptz DEFAULT now(), about text, document_url text, pan_number text, aadhaar_number text, emergency_contact_name text, emergency_contact_phone text, emergency_contact_address text, kyc_document_url text, recruiter_role text DEFAULT 