andidates ADD CONSTRAINT saved_candidates_recruiter_id_fkey FOREIGN KEY (recruiter_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: saved_candidates\nALTER TABLE saved_candidates ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: saved_candidates\nCREATE POLICY project_admin_policy ON saved_candidates FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: saved_jobs\nCREATE TABLE IF NOT EXISTS saved_jobs (id uuid NOT NULL DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL, job_id uuid NOT NULL, saved_at timestamptz DEFAULT now());\n\n-- Indexes for table: saved_jobs\nCREATE INDEX idx_saved_jobs_job_id ON public.saved_jobs USING btree (job_id);\nCREATE UNIQUE INDEX saved_jobs_candidate_id_job_id_key ON public.saved_jobs USING btree (candidate_id, job_id);\n\n-- Foreign key constraints for table: saved_jobs\nALTER TABLE saved_jobs ADD CONSTRAINT saved_jobs_job_id_fkey FOREIGN KEY (job_id) REFERENCES jobs (id);\n\n-- RLS enabled for table: saved_jobs\nALTER TABLE saved_jobs ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: saved_jobs\nCREATE POLICY \"Saved jobs access\" ON saved_jobs FOR ALL TO public USING ((candidate_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY project_admin_policy ON saved_jobs FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Data for table: saved_jobs\nINSERT INTO saved_jobs (id, candidate_id, job_id, saved_at) VALUES ('9219fdd1-c189-4bf5-b7d2-8661a291b21e', '464fd40c-d5dd-4aca-8a8c-c1dad7a9149b', 'a21df5b6-30d6-47d4-8d40-f451f38caf29', '2026-04-06T07:17:35.536Z');\nINSERT INTO saved_jobs (id, candidate_id, job_id, saved_at) VALUES ('75dfdc48-51c2-4933-b178-d5e523b55eee', 'cf11301b-50f8-41e7-8191-46713a735c4e', '0033875b-bd44-482c-a1d9-41aeb54c36f2', '2026-06-08T07:42:58.191Z');\nINSERT INTO saved_jobs (id, candidate_id, job_id, saved_at) VALUES ('cee15579-67d2-4944-a40b-486a5e76a2cf', 'f7c08e25-30b9-40c1-94f2-5e5ec8806406', '0033875b-bd44-482c-a1d9-41aeb54c36f2', '2026-