for table: subscription_events\nALTER TABLE subscription_events ADD CONSTRAINT subscription_events_recruiter_id_fkey FOREIGN KEY (recruiter_id) REFERENCES profiles (id);\n\n-- RLS enabled for table: subscription_events\nALTER TABLE subscription_events ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: subscription_events\nCREATE POLICY admin_bypass ON subscription_events FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON subscription_events FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: subscriptions\nCREATE TABLE IF NOT EXISTS subscriptions (id uuid NOT NULL DEFAULT gen_random_uuid(), company_id uuid, recruiter_id uuid, plan text NOT NULL DEFAULT 'starter'::text, status text NOT NULL DEFAULT 'trialing'::text, billing_cycle text DEFAULT 'monthly'::text, amount_inr numeric DEFAULT 0, trial_ends_at timestamptz, current_period_start timestamptz DEFAULT now(), current_period_end timestamptz DEFAULT (now() + '30 days'::interval), cancelled_at timestamptz, notes text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());\n\n-- Indexes for table: subscriptions\nCREATE INDEX idx_subscriptions_company_id ON public.subscriptions USING btree (company_id);\n\n-- Foreign key constraints for table: subscriptions\nALTER TABLE subscriptions ADD CONSTRAINT subscriptions_company_id_fkey FOREIGN KEY (company_id) REFERENCES companies (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: subscriptions\nALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: subscriptions\nCREATE POLICY \"Admins can manage subscriptions\" ON subscriptions FOR ALL TO public USING (is_admin());\nCREATE POLICY admin_bypass_subscriptions ON subscriptions FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON subscriptions FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: test_rpc_sync\nCREATE TABLE IF NOT EXISTS test_rpc_sync (