ic USING (is_admin());\nCREATE POLICY \"Admins can view all preferences\" ON user_preferences FOR SELECT TO public USING (is_admin());\nCREATE POLICY \"Users can insert own preferences\" ON user_preferences FOR INSERT TO public WITH CHECK ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Users can update own preferences\" ON user_preferences FOR UPDATE TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Users can view own preferences\" ON user_preferences FOR SELECT TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY admin_bypass ON user_preferences FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON user_preferences FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Triggers for table: user_preferences\nCREATE TRIGGER update_user_preferences_timestamp_trig BEFORE UPDATE ON user_preferences FOR EACH ROW EXECUTE FUNCTION update_user_preferences_timestamp();\n\n-- Data for table: user_preferences\nINSERT INTO user_preferences (user_id, sidebar_preferences, dashboard_preferences, updated_at) VALUES ('4c926507-915c-494f-9468-683620b9c33f', '{\"width\":280,\"version\":1,\"collapsed\":false}', '{}', '2026-06-21T11:41:52.461Z');\n\n-- Table: user_rate_limits\nCREATE TABLE IF NOT EXISTS user_rate_limits (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, timestamp timestamptz NOT NULL DEFAULT now());\n\n-- Indexes for table: user_rate_limits\nCREATE INDEX idx_user_rate_limits_user_id ON public.user_rate_limits USING btree (user_id);\n\n-- Foreign key constraints for table: user_rate_limits\nALTER TABLE user_rate_limits ADD CONSTRAINT user_rate_limits_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: user_rate_limits\nALTER TABLE user_rate_limits ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: user_rate_limits\nCREATE POLICY admin_bypass ON user_rate_limits FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON user_rate_limits FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Table: user_sessions\nCREATE TABLE IF NOT EXISTS user_sessions (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid, session_type text DEFAULT 'normal'::text, token_fingerprint text NOT NULL, session_name text, ip_hash text NOT NULL, user_agent text, country text, region text, created_at timestamptz DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, last_active_at timestamptz DEFAULT now(), impersonation_started_at timestamptz, impersonated_by uuid, session_version integer NOT NULL DEFAULT 1);\n\n-- Indexes for table: user_sessions\nCREATE INDEX idx_user_sessions_impersonated_by ON public.user_sessions USING btree (impersonated_by);\nCREATE INDEX idx_user_sessions_user_id ON public.user_sessions USING btree (user_id);\nCREATE UNIQUE INDEX user_sessions_token_fingerprint_key ON public.user_sessions USING btree (token_fingerprint);\n\n-- Foreign key constraints for table: user_sessions\nALTER TABLE user_sessions ADD CONSTRAINT user_sessions_impersonated_by_fkey FOREIGN KEY (impersonated_by) REFERENCES profiles (id) ON DELETE SET NULL;\nALTER TABLE user_sessions ADD CONSTRAINT user_sessions_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles (id) ON DELETE CASCADE;\n\n-- RLS enabled for table: user_sessions\nALTER TABLE user_sessions ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for table: user_sessions\nCREATE POLICY \"Admins can manage user_sessions\" ON user_sessions FOR ALL TO public USING (is_admin()) WITH CHECK (is_admin());\nCREATE POLICY \"Users can revoke own sessions\" ON user_sessions FOR UPDATE TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY \"Users can view own sessions\" ON user_sessions FOR SELECT TO public USING ((user_id = ( SELECT auth.uid() AS uid)));\nCREATE POLICY admin_bypass ON user_sessions FOR ALL TO project_admin USING (true) WITH CHECK (true);\nCREATE POLICY project_admin_policy ON user_sessions FOR ALL TO project_admin USING (true) WITH CHECK (true);\n\n-- Data for table: user_sessions\nINSERT INTO user_sessions (id, user_id, session_type, token_fingerprint, session_name, ip_hash, user_agent, country, region, created_at, expires_at, revoked_at, last_active_at, impersonation_started_at, impersonated_by, session_version) VALUES ('c4e9a5d1-f98f-48a3-b9c5-c3c23f5a306a', '18d329f1-7301-4359-91b4-595f948f4342', 'normal', 'b4af70ab35aedf4b849520a37e185a7e9136435aa4febf7084082f44882add8d', 'Chrome • Windows', '54f04d724c13df140a7c7da5e6895a1e08d99d91e6f6376d419496602197028e', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36', 'Unknown', 'Unknown', '2026-06-11T11:58:58.019Z', '2026-07-11T11:58:57.961Z', NULL, '2026-06-11T11:58:57.961Z', NULL, NULL, 1);\nINSERT INTO user_sessions (id, user_id, session_type, token_fingerprint, session_name, ip_hash, user_agent, country, region, created_at, expires_at, revoked_at, last_active_at, impersonation_started_at, impersonated_by, session_version) VALUES ('a4f0a6f2-bff7-4482-8c23-dd8baed186e8', '18d329f1-7301-4359-91b4-595f948f4342', 'normal', '411f06508a1da8a9d71257890e4bd8c0b812fecc0beff27082c5379503da808b', 'Chrome • Windows', '0d8301903faef21ad4488ef383651a3863b5057915262af6be1a5ec329d80153', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36', 'Unknown', 'Unknown', '2026-06-11T12:00:07.101Z', '2026-07-11T12:00:07.046Z', NULL, '2026-06-11T12:00:07.046Z', NULL, NULL, 1);\nINSERT INTO user_sessions (id, user_id, session_type, token_fingerprint, session_name, ip_hash, user_agent, country, region, created_at, expires_at, revoked_at, last_active_at, impersonation_started_at, impersonated_by, session_version) VALUES ('6d86b058-cea2-4e37-ad36-4204fa020535', '18d329f1-7301-4359-91b4-595f948f4342', 'normal', 'a33d1ee1a703de10d32b0b2c320967e957724808b867