8ec7b8a9eaf4499cd0a01341e629aa167c568945e4269a9fc3', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36', 'IN', 'Unknown', '2026-07-07T10:56:06.354Z', '2026-08-06T10:56:06.286Z', '2026-07-07T11:06:07.346Z', '2026-07-07T11:05:01.985Z', NULL, NULL, 1);\nINSERT INTO user_sessions (id, user_id, session_type, token_fingerprint, session_name, ip_hash, user_agent, country, region, created_at, expires_at, revoked_at, last_active_at, impersonation_started_at, impersonated_by, session_version) VALUES ('e56fff74-fd7b-4cde-ab69-977b6361f876', '4c926507-915c-494f-9468-683620b9c33f', 'normal', 'b1f6f3182e354b2adeeb9134df8b508f8e07fab5d02fe267928b3bb95936655a', 'Chrome • Windows', '684576eab3cc488ec7b8a9eaf4499cd0a01341e629aa167c568945e4269a9fc3', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36', 'IN', 'Unknown', '2026-07-07T05:10:33.024Z', '2026-08-06T05:10:32.971Z', NULL, '2026-07-07T05:21:57.555Z', NULL, NULL, 1);\nINSERT INTO user_sessions (id, user_id, session_type, token_fingerprint, session_name, ip_hash, user_agent, country, region, created_at, expires_at, revoked_at, last_active_at, impersonation_started_at, impersonated_by, session_version) VALUES ('e1e3e863-1b8b-4bfb-93e1-30a6fa08653f', '4c926507-915c-494f-9468-683620b9c33f', 'normal', '7fee3bd26f5263c061d5906bb30cd05ed03a3c174f62b4227a17c6df48644879', 'Chrome • Windows', 'd738571390c74aae72b0da31fe9dc9e41a9303981703f72d6691a542a10ec600', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/149.0.0.0 Safari/537.36', 'IN', 'Unknown', '2026-07-07T04:55:13.681Z', '2026-08-06T04:55:13.619Z', NULL, '2026-07-07T05:08:43.024Z', NULL, NULL, 1);\nINSERT INTO user_sessions (id, user_id, session_type, token_fingerprint, session_name, ip_hash, user_agent, country, region, created_at, expires_at, revoked_at, last_active_at, impersonation_started_at, impersonated_by, session_version) VALUES ('ba06cbc2-f1a3-4df8-9a2e-1947b5a237bc', '18d329f1-7301-4359-91b4-595f948f4342', 'normal', 'e6a1a8cfe0342d7ffde9b0fcfc306020dbb89e46a4c8e082f5592cdcabb1cb3d', 'Safari • macOS', '684576eab3cc488ec7b8a9eaf4499cd0a01341e629aa167c568945e4269a9fc3', 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_7 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/26.5 Mobile/15E148 Safari/604.1', 'IN', 'Unknown', '2026-07-07T11:21:03.708Z', '2026-08-06T11:21:03.630Z', NULL, '2026-07-07T11:21:47.738Z', NULL, NULL, 1);\n\n-- Functions and Procedures\n-- Function: calculate_profile_strength_score\nCREATE OR REPLACE FUNCTION public.calculate_profile_strength_score(user_uuid uuid)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n    score INTEGER := 0;\n    prof RECORD;\n    cand RECORD;\nBEGIN\n    -- Get profiles row\n    SELECT avatar_url, bio, location INTO prof FROM public.profiles WHERE id = user_uuid;\n    -- Get candidate_profiles row\n    SELECT resume_url, skills, work_history, education, linkedin_url INTO cand FROM public.candidate_profiles WHERE id = user_uuid;\n\n    -- 1. avatar_url (10 points)\n    IF prof.avatar_url IS NOT NULL AND prof.avatar_url <> '' THEN\n        score := score + 10;\n    END IF;\n\n    -- 2. resume_url (20 points)\n    IF cand.resume_url IS NOT NULL AND cand.resume_url <> '' THEN\n        score := score + 20;\n    END IF;\n\n    -- 3. bio (15 points, >= 30 chars)\n    IF prof.bio IS NOT NULL AND length(trim(prof.bio)) >= 30 THEN\n        score := score + 15;\n    END IF;\n\n    -- 4. skills (15 points, >= 5 skills)\n    IF cand.skills IS NOT NULL THEN\n        IF array_length(cand.skills, 1) >= 5 THEN\n            score := score + 15;\n        END IF;\n    END IF;\n\n    -- 5. work_history (15 points, >= 1 entries)\n    IF cand.work_history IS NOT NULL AND jsonb_typeof(cand.work_history) = 'array' THEN\n        IF jsonb_array_length(cand.work_history) >= 1 THEN\n            score := score + 15;\n        END IF;\n    END IF;\n\n    -- 6. education (10 points, >= 1 entries or non-empty string)\n    IF cand.education IS NOT NULL THEN\n        IF jsonb_typeof(cand.education) = 'array' THEN\n            IF jsonb_array_length(cand.education) >= 1 THEN\n                score := score + 10;\n            END IF;\n        ELSIF jsonb_typeof(cand.education) = 'string' AND length(trim(cand.education::text)) > 2 THEN\n            IF length(trim(cand.education#>>'{}')) > 0 THEN\n                score := score + 10;\n            END IF;\n        END IF;\n    END IF;\n\n    -- 7. linkedin_url (10 points)\n    IF cand.linkedin_url IS NOT NULL AND cand.linkedin_url <> '' THEN\n        score := score + 10;\n    END IF;\n\n    -- 8. location (5 points)\n    IF prof.location IS NOT NULL AND prof.location <> '' THEN\n        score := score + 5;\n    END IF;\n\n    RETURN score;\nEND;\n$function$\n;\n\n-- Function: check_direct_application_status_update\nCREATE OR REPLACE FUNCTION public.check_direct_application_status_update()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nDECLARE\r\n  v_actor_id TEXT;\r\n  v_actor_type TEXT;\r\nBEGIN\r\n  -- Block direct updates to the status column unless called via update_application_status RPC\r\n  IF (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status) THEN\r\n    BEGIN\r\n      v_actor_id := NULLIF(current_setting('app.current_actor_id', true), '');\r\n    EXCEPTION WHEN OTHERS THEN\r\n      v_actor_id := NULL;\r\n    END;\r\n\r\n    BEGIN\r\n      v_actor_type := NULLIF(current_setting('app.current_actor_type', true), '');\r\n    EXCEPTION WHEN OTHERS THEN\r\n      v_actor_type := NULL;\r\n    END;\r\n\r\n    IF v_actor_id IS NULL OR v_actor_type IS NULL THEN\r\n      RAISE EXCEPTION 'Direct updates to application status are blocked. Use the update_application_status RPC.';\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n;\n\n-- Function: check_max_resumes_limit\nCREATE OR REPLACE FUNCTION public.check_max_resumes_limit()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  v_count INTEGER;\nBEGIN\n  SELECT COUNT(*) INTO v_count FROM public.candidate_resumes WHERE candidate_id = NEW.candidate_id;\n  IF v_count >= 5 THEN\n    RAISE EXCEPTION 'Maximum limit of 5 resumes reached.';\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n;\n\n-- Function: check_notification_throttle\nCREATE OR REPLACE FUNCTION public.check_notification_throttle()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n  recent_count INTEGER;\nBEGIN\n  -- Count notifications for this user in the last minute (excluding failed or throttled)\n  SELECT COUNT(*) INTO recent_count\n  FROM public.notification_jobs\n  WHERE user_id = NEW.user_id\n    AND created_at > now() - INTERVAL '1 minute'\n    AND status IN ('pending', 'queued', 'sent', 'delivered');\n\n  IF recent_count >= 5 THEN\n    NEW.status := 'throttled';\n    NEW.next_attempt_at := now() + INTERVAL '1 minute';\n  END IF;\n\n  RETURN NEW;\nEND;\n$function$\n;\n\n-- Function: check_primary_resume_ownership\nCREATE OR REPLACE FUNCTION public.check_primary_resume_ownership()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF NEW.primary_resume_id IS NOT NULL THEN\n    IF NOT EXISTS (\n      SELECT 1 FROM public.candidate_resumes\n      WHERE id = NEW.primary_resume_id\n      AND candidate_id = NEW.id\n    ) THEN\n      RAISE EXCEPTION 'Primary resume does not belong to the candidate.';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n;\n\n-- Function: claim_cleanup_lock\nCREATE OR REPLACE FUNCTION public.claim_cleanup_lock(job_name_val text, worker_val text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  success BOOLEAN := FALSE;\nBEGIN\n  -- Clean up old completed locks first\n  DELETE FROM public.cleanup_job_runs\n  WHERE job_name = job_name_val\n    AND (completed_at IS NOT NULL OR started_at < now() - interval '10 minutes');\n\n  INSERT INTO public.cleanup_job_runs (job_name, started_at, locked_by)\n  VALUES (job_name_val, now(), worker_val)\n  ON CONFLICT (job_name) DO UPDATE\n  SET started_at = now(),\n      completed_at = NULL,\n      locked_by = worker_val\n  WHERE public.cleanup_job_runs.completed_at IS NOT NULL\n     OR public.cleanup_job_runs.started_at < now() - interval '10 minutes';\n     \n  IF FOUND THEN\n    success := TRUE;\n  END IF;\n  \n  RETURN success;\nEND;\n$function$\n;\n\n-- Function: claim_export_job\nCREATE OR REPLACE FUNCTION public.claim_export_job(job_id uuid, worker_id text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  claimed BOOLEAN := FALSE;\nBEGIN\n  UPDATE public.export_jobs\n  SET status = 'running',\n      locked_by = worker_id,\n      locked_at = now(),\n      started_at = now()\n  WHERE id = job_id\n    AND (status = 'pending' OR (status = 'running' AND locked_at < now() - INTERVAL '10 minutes'))\n    AND (user_id = auth.uid() OR EXISTS (\n      SELECT 1 FROM public.profiles \n      WHERE id = auth.uid() AND role IN ('admin', 'super_admin')\n    ));\n\n  IF FOUND THEN\n    claimed := TRUE;\n  END IF;\n\n  RETURN claimed;\nEND;\n$function$\n;\n\n-- Function: claim_notification_job\nCREATE OR REPLACE FUNCTION public.claim_notification_job(worker_id text, lease_duration interval)\n RETURNS TABLE(id uuid, user_id uuid, template_id uuid, channel text, status text, priority text, title text, message text, payload jsonb, dedupe_key text, retry_count integer, last_error text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  claimed_id UUID;\nBEGIN\n  -- Find the highest priority pending, expired-lease running, or next-attempt due throttled/failed job\n  SELECT j.id INTO claimed_id\n  FROM public.notification_jobs j\n  WHERE (\n      -- Pending jobs\n      j.status = 'pending'\n      -- Stuck running jobs with expired leases\n      OR (j.status = 'queued' AND (j.lease_expires_at IS NULL OR j.lease_expires_at < now()))\n      -- Throttled jobs that are ready for retry\n      OR (j.status = 'throttled' AND j.next_attempt_at <= now())\n      -- Failed jobs that are ready for retry\n      OR (j.status = 'failed' AND j.retry_count < 3 AND j.next_attempt_at <= now())\n    )\n    AND j.expires_at > now()\n  ORDER BY \n    CASE j.priority\n      WHEN 'critical' THEN 1\n      WHEN 'high' THEN 2\n      WHEN 'normal' THEN 3\n      WHEN 'low' THEN 4\n      ELSE 5\n    END ASC,\n    j.created_at ASC\n  LIMIT 1\n  FOR UPDATE SKIP LOCKED;\n\n  IF claimed_id IS NOT NULL THEN\n    UPDATE public.notification_jobs j\n    SET status = 'queued',\n        locked_by = worker_id,\n        locked_at = now(),\n        heartbeat_at = now(),\n        lease_expires_at = now() + lease_duration,\n        updated_at = now()\n    WHERE j.id = claimed_id;\n\n    RETURN QUERY\n    SELECT \n      j.id,\n      j.user_id,\n      j.template_id,\n      j.channel,\n      j.status,\n      j.priority,\n      j.title,\n      j.message,\n      j.payload,\n      j.dedupe_key,\n      j.retry_count,\n      j.last_error\n    FROM public.notification_jobs j\n    WHERE j.id = claimed_id;\n  END IF;\nEND;\n$function$\n;\n\n-- Function: cleanup_exports\nCREATE OR REPLACE PROCEDURE public.cleanup_exports(IN worker_val text, OUT deleted_count integer)\n LANGUAGE plpgsql\nAS $procedure$\nDECLARE\n  start_time TIMESTAMPTZ := now();\n  duration_ms INTEGER;\nBEGIN\n  deleted_count := 0;\n  IF public.claim_cleanup_lock('cleanup_exports', worker_val) THEN\n    -- Delete export jobs older than 7 days\n    DELETE FROM public.export_jobs\n    WHERE created_at < now() - interval '7 days';\n      \n    GET DIAGNOSTICS deleted_count = ROW_COUNT;\n    \n    PERFORM public.release_cleanup_lock('cleanup_exports', worker_val);\n    \n    duration_ms := extract(epoch from (now() - start_time)) * 1000;\n    PERFORM public.log_cleanup_telemetry('cleanup_exports', deleted_count, duration_ms);\n  END IF;\nEND;\n$procedure$\n;\n\n-- Function: cleanup_idempotency\nCREATE OR REPLACE PROCEDURE public.cleanup_idempotency(IN worker_val text, OUT deleted_count integer)\n LANGUAGE plpgsql\nAS $procedure$\nDECLARE\n  start_time TIMESTAMPTZ := now();\n  duration_ms INTEGER;\nBEGIN\n  deleted_count := 0;\n  IF public.claim_cleanup_lock('cleanup_idempotency', worker_val) THEN\n    -- Clean up expired idempotency keys\n    DELETE FROM public.idempotency_keys\n    WHERE expires_at < now();\n      \n    GET DIAGNOSTICS deleted_count = ROW_COUNT;\n    \n    PERFORM public.release_cleanup_lock('cleanup_idempotency', worker_val);\n    \n    duration_ms := extract(epoch from (now() - start_time)) * 1000;\n    PERFORM public.log_cleanup_telemetry('cleanup_idempotency', deleted_count, duration_ms);\n  END IF;\nEND;\n$procedure$\n;\n\n-- Function: cleanup_notifications\nCREATE OR REPLACE PROCEDURE public.cleanup_notifications(IN worker_val text, OUT deleted_count integer)\n LANGUAGE plpgsql\nAS $procedure$\nDECLARE\n  start_time TIMESTAMPTZ := now();\n  duration_ms INTEGER;\nBEGIN\n  deleted_count := 0;\n  IF public.claim_cleanup_lock('cleanup_notifications', worker_val) THEN\n    -- Delete notification jobs older than 7 days\n    DELETE FROM public.notification_jobs\n    WHERE expires_at < now()\n      AND created_at < now() - interval '7 days';\n      \n    GET DIAGNOSTICS deleted_count = ROW_COUNT;\n    \n    PERFORM public.release_cleanup_lock('cleanup_notifications', worker_val);\n    \n    duration_ms := extract(epoch from (now() - start_time)) * 1000;\n    PERFORM public.log_cleanup_telemetry('cleanup_notifications', deleted_count, duration_ms);\n  END IF;\nEND;\n$procedure$\n;\n\n-- Function: cleanup_sessions\nCREATE OR REPLACE PROCEDURE public.cleanup_sessions(IN worker_val text, OUT deleted_count integer)\n LANGUAGE plpgsql\nAS $procedure$\nDECLARE\n  start_time TIMESTAMPTZ := now();\n  duration_ms INTEGER;\nBEGIN\n  deleted_count := 0;\n  IF public.claim_cleanup_lock('cleanup_sessions', worker_val) THEN\n    -- Delete revoked or expired sessions older than 7 days\n    DELETE FROM public.user_sessions\n    WHERE (expires_at < now() OR revoked_at IS NOT NULL)\n      AND last_active_at < now() - interval '7 days';\n      \n    GET DIAGNOSTICS deleted_count = ROW_COUNT;\n    \n    PERFORM public.release_cleanup_lock('cleanup_sessions', worker_val);\n    \n    duration_ms := extract(epoch from (now() - start_time)) * 1000;\n    PERFORM public.log_cleanup_telemetry('cleanup_sessions', deleted_count, duration_ms);\n  END IF;\nEND;\n$procedure$\n;\n\n-- Function: cleanup_storage\nCREATE OR REPLACE PROCEDURE public.cleanup_storage(IN worker_val text, OUT deleted_count integer)\n LANGUAGE plpgsql\nAS $procedure$\nDECLARE\n  start_time TIMESTAMPTZ := now();\n  duration_ms INTEGER;\nBEGIN\n  deleted_count := 0;\n  IF public.claim_cleanup_lock('cleanup_storage', worker_val) THEN\n    -- Purge database quarantine records that are older than 7 days and not restored\n    UPDATE public.storage_quarantine\n    SET status = 'deleted'\n    WHERE status = 'quarantined'\n      AND expires_at < now();\n      \n    GET DIAGNOSTICS deleted_count = ROW_COUNT;\n    \n    PERFORM public.release_cleanup_lock('cleanup_storage', worker_val);\n    \n    duration_ms := extract(epoch from (now() - start_time)) * 1000;\n    PERFORM public.log_cleanup_telemetry('cleanup_storage', deleted_count, duration_ms);\n  END IF;\nEND;\n$procedure$\n;\n\n-- Function: create_trigger_safe\nCREATE OR REPLACE PROCEDURE public.create_trigger_safe(IN tr_name text, IN tbl_name text, IN stmt text)\n LANGUAGE plpgsql\nAS $procedure$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = tr_name) THEN EXECUTE stmt; END IF;\nEND; $procedure$\n;\n\n-- Function: exec_sql\nCREATE OR REPLACE FUNCTION public.exec_sql(query text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  result jsonb;\nBEGIN\n  EXECUTE query;\n  RETURN '{\"success\": true}'::jsonb;\nEXCEPTION WHEN OTHERS THEN\n  RETURN jsonb_build_object('success', false, 'error', SQLERRM);\nEND;\n$function$\n;\n\n-- Function: handle_new_profile_prefs\nCREATE OR REPLACE FUNCTION public.handle_new_profile_prefs()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  INSERT INTO public.notification_preferences (user_id)\n  VALUES (NEW.id)\n  ON CONFLICT (user_id) DO NOTHING;\n  RETURN NEW;\nEND;\n$function$\n;\n\n-- Function: handle_new_user\nCREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nDECLARE\n  v_role TEXT;\n  v_name TEXT;\nBEGIN\n  -- Read role and name from metadata if available\n  -- Fall back safely if metadata columns don't exist in this InsForge version\n  BEGIN\n    v_role := COALESCE(\n      (NEW.raw_user_meta_data->>'role'),\n      'candidate'\n    );\n    v_name := COALESCE(\n      (NEW.raw_user_meta_data->>'name'),\n      split_part(NEW.email, '@', 1)\n    );\n  EXCEPTION WHEN undefined_column THEN\n    v_role := 'candidate';\n    v_name := split_part(NEW.email, '@', 1);\n  END;\n\n  INSERT INTO public.profiles (id, role, name, email, created_at)\n  VALUES (NEW.id, v_role, v_name, COALESCE(NEW.email, ''), NOW())\n  ON CONFLICT (id) DO NOTHING;\n\n  RETURN NEW;\nEND;\n$function$\n;\n\n-- Function: handle_password_change_invalidation\nCREATE OR REPLACE FUNCTION public.handle_password_change_invalidation()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nBEGIN\n  IF (OLD.password_set_at IS DISTINCT FROM NEW.password_set_at) THEN\n    -- Increment session version and set rotation reason\n    INSERT INTO public.user_auth_state (user_id, session_version, rotated_at, reason)\n    VALUES (NEW.id, 2, NOW(), 'PASSWORD_ROTATED')\n    ON CONFLICT (user_id) DO UPDATE\n    SET session_version = public.user_auth_state.session_version + 1,\n        rotated_at = NOW(),\n        reason = 'PASSWORD_ROTATED';\n        \n    -- Log event to auth_events\n    INSERT INTO public.auth_events (user_id, event_type)\n    VALUES (NEW.id, 'PASSWORD_ROTATED');\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n;\n\n-- Function: increment_announcement_dismiss\nCREATE OR REPLACE FUNCTION public.increment_announcement_dismiss(ann_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nBEGIN\n  UPDATE public.announcements SET dismiss_count = dismiss_count + 1 WHERE id = ann_id;\nEND;\n$function$\n;\n\n-- Function: increment_announcement_view\nCREATE OR REPLACE FUNCTION public.increment_announcement_view(ann_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nBEGIN\n  UPDATE public.announcements SET view_count = view_count + 1 WHERE id = ann_id;\nEND;\n$function$\n;\n\n-- Function: is_admin\nCREATE OR REPLACE FUNCTION public.is_admin()\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  is_adm BOOLEAN;\r\nBEGIN\r\n  IF auth.uid() IS NULL THEN\r\n    RETURN FALSE;\r\n  END IF;\r\n  \r\n  -- Querying admin_users never triggers RLS as RLS is disabled on it\r\n  SELECT EXISTS (\r\n    SELECT 1 FROM public.admin_users WHERE user_id = auth.uid()\r\n  ) INTO is_adm;\r\n  \r\n  RETURN is_adm;\r\nEND;\r\n$function$\n;\n\n-- Function: is_recruiter\nCREATE OR REPLACE FUNCTION public.is_recruiter()\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE\n  is_rec BOOLEAN;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RETURN FALSE;\n  END IF;\n  SELECT EXISTS (\n    SELECT 1 FROM public.recruiter_users WHERE user_id = auth.uid()\n  ) INTO is_rec;\n  RETURN is_rec;\nEND;\n$function$\n;\n\n-- Function: log_admin_action\nCREATE OR REPLACE FUNCTION public.log_admin_action(p_actor_id uuid, p_action text, p_table text DEFAULT NULL::text, p_record_id uuid DEFAULT NULL::uuid, p_old_data jsonb DEFAULT NULL::jsonb, p_new_data jsonb DEFAULT NULL::jsonb, p_ip inet DEFAULT NULL::inet)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nBEGIN\n  INSERT INTO audit_logs(actor_id, action, table_name, record_id, old_data, new_data, ip_address)\n  VALUES (p_actor_id, p_action, p_table, p_record_id, p_old_data, p_new_data, p_ip);\nEND;\n$function$\n;\n\n-- Function: log_application_status_change\nCREATE OR REPLACE FUNCTION public.log_application_status_change()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  v_actor_id UUID;\n  v_actor_type TEXT;\nBEGIN\n  -- Attempt to read from transaction-local config variables, fallback to auth.uid()\n  BEGIN\n    v_actor_id := NULLIF(current_setting('app.current_actor_id', true), '')::UUID;\n  EXCEPTION WHEN OTHERS THEN\n    v_actor_id := NULL;\n  END;\n\n  BEGIN\n    v_actor_type := NULLIF(current_setting('app.current_actor_type', true), '');\n  EXCEPTION WHEN OTHERS THEN\n    v_actor_type := NULL;\n  END;\n\n  IF v_actor_id IS NULL THEN\n    BEGIN\n      v_actor_id := auth.uid()::UUID;\n    EXCEPTION WHEN OTHERS THEN\n      v_actor_id := NULL;\n    END;\n  END IF;\n\n  IF v_actor_type IS NULL THEN\n    IF v_actor_id IS NOT NULL THEN\n      -- Lookup profile role to set actor_type\n      SELECT role INTO v_actor_type FROM public.profiles WHERE id = v_actor_id;\n      IF v_actor_type IN ('admin', 'super_admin') THEN\n        v_actor_type := 'admin';\n      ELSIF v_actor_type = 'recruiter' THEN\n        v_actor_type := 'recruiter';\n      ELSE\n        v_actor_type := 'candidate';\n      END IF;\n    ELSE\n      v_actor_type := 'system';\n    END IF;\n  END IF;\n\n  IF (TG_OP = 'INSERT') THEN\n    INSERT INTO public.application_status_history (\n      application_id, from_status, to_status, changed_by, actor_type, note\n    ) VALUES (\n      NEW.id, NULL, NEW.status, v_actor_id, v_actor_type, 'Application submitted'\n    );\n  ELSIF (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status) THEN\n    INSERT INTO public.application_status_history (\n      application_id, from_status, to_status, changed_by, actor_type, note\n    ) VALUES (\n      NEW.id, OLD.status, NEW.status, v_actor_id, v_actor_type, \n      CASE \n        WHEN NEW.status = 'withdrawn' THEN 'Application withdrawn by candidate'\n        ELSE 'Status updated'\n      END\n    );\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n;\n\n-- Function: log_cleanup_telemetry\nCREATE OR REPLACE FUNCTION public.log_cleanup_telemetry(job_name_val text, deleted_count_val integer, duration_ms_val integer, metadata_val jsonb DEFAULT '{}'::jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nBEGIN\n  INSERT INTO public.audit_log (entity_type, entity_id, action, performed_by, metadata)\n  VALUES (\n    'cleanup_job',\n    NULL,\n    job_name_val || ':completed',\n    '00000000-0000-0000-0000-000000000000'::uuid, -- System user placeholder or null\n    jsonb_build_object(\n      'job_name', job_name_val,\n      'deleted_count', deleted_count_val,\n      'duration_ms', duration_ms_val,\n      'run_at', now()\n    ) || metadata_val\n  );\nEND;\n$function$\n;\n\n-- Function: maintain_resume_upload_count\nCREATE OR REPLACE FUNCTION public.maintain_resume_upload_count()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\r\nBEGIN\r\n  IF TG_OP = 'INSERT' THEN\r\n    IF NEW.resume_id IS NOT NULL AND NEW.status != 'withdrawn' THEN\r\n      UPDATE public.candidate_resumes\r\n      SET upload_count = COALESCE(upload_count, 0) + 1\r\n      WHERE id = NEW.resume_id;\r\n    END IF;\r\n  ELSIF TG_OP = 'DELETE' THEN\r\n    IF OLD.resume_id IS NOT NULL AND OLD.status != 'withdrawn' THEN\r\n      UPDATE public.candidate_resumes\r\n      SET upload_count = GREATEST(0, COALESCE(upload_count, 0) - 1)\r\n      WHERE id = OLD.resume_id;\r\n    END IF;\r\n  ELSIF TG_OP = 'UPDATE' THEN\r\n    IF OLD.resume_id IS DISTINCT FROM NEW.resume_id OR OLD.status IS DISTINCT FROM NEW.status THEN\r\n      -- Decrement upload count for old state if applicable\r\n      IF OLD.resume_id IS NOT NULL AND OLD.status != 'withdrawn' THEN\r\n        UPDATE public.candidate_resumes\r\n        SET upload_count = GREATEST(0, COALESCE(upload_count, 0) - 1)\r\n        WHERE id = OLD.resume_id;\r\n      END IF;\r\n      -- Increment upload count for new state if applicable\r\n      IF NEW.resume_id IS NOT NULL AND NEW.status != 'withdrawn' THEN\r\n        UPDATE public.candidate_resumes\r\n        SET upload_count = COALESCE(upload_count, 0) + 1\r\n        WHERE id = NEW.resume_id;\r\n      END IF;\r\n    END IF;\r\n  END IF;\r\n  RETURN NULL;\r\nEND;\r\n$function$\n;\n\n-- Function: query_json\nCREATE OR REPLACE FUNCTION public.query_json(query_text text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\n        DECLARE\n          result jsonb;\n        BEGIN\n          EXECUTE 'SELECT jsonb_agg(t) FROM (' || query_text || ') t' INTO result;\n          RETURN result;\n        END;\n        $function$\n;\n\n-- Function: reassign_resume_references\nCREATE OR REPLACE FUNCTION public.reassign_resume_references()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\r\nDECLARE\r\n  v_new_resume RECORD;\r\n  v_primary_id UUID;\r\n  v_resume_url TEXT;\r\nBEGIN\r\n  -- Get the current primary_resume_id and resume_url from candidate_profiles\r\n  SELECT primary_resume_id, resume_url INTO v_primary_id, v_resume_url\r\n  FROM public.candidate_profiles\r\n  WHERE id = OLD.candidate_id;\r\n\r\n  -- Check if we need to reassign references\r\n  IF OLD.is_default OR v_primary_id = OLD.id OR v_resume_url = OLD.file_url THEN\r\n    -- Find the newest remaining resume for this candidate (excluding the one being deleted)\r\n    SELECT * INTO v_new_resume\r\n    FROM public.candidate_resumes\r\n    WHERE candidate_id = OLD.candidate_id AND id != OLD.id\r\n    ORDER BY created_at DESC\r\n    LIMIT 1;\r\n\r\n    IF v_new_resume.id IS NOT NULL THEN\r\n      -- If the deleted one was default, make the new one default\r\n      IF OLD.is_default THEN\r\n        UPDATE public.candidate_resumes\r\n        SET is_default = true\r\n        WHERE id = v_new_resume.id;\r\n      END IF;\r\n\r\n      -- Update candidate profiles\r\n      UPDATE public.candidate_profiles\r\n      SET \r\n        primary_resume_id = CASE \r\n          WHEN primary_resume_id = OLD.id THEN v_new_resume.id \r\n          ELSE primary_resume_id \r\n        END,\r\n        resume_url = CASE \r\n          WHEN OLD.is_default OR resume_url = OLD.file_url THEN v_new_resume.file_url \r\n          ELSE resume_url \r\n        END\r\n      WHERE id = OLD.candidate_id;\r\n\r\n    ELSE\r\n      -- No remaining resumes, clear references\r\n      UPDATE public.candidate_profiles\r\n      SET primary_resume_id = NULL,\r\n          resume_url = NULL\r\n      WHERE id = OLD.candidate_id;\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN OLD;\r\nEND;\r\n$function$\n;\n\n-- Function: release_cleanup_lock\nCREATE OR REPLACE FUNCTION public.release_cleanup_lock(job_name_val text, worker_val text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nBEGIN\n  UPDATE public.cleanup_job_runs\n  SET completed_at = now(),\n      locked_by = NULL\n  WHERE job_name = job_name_val\n    AND locked_by = worker_val;\nEND;\n$function$\n;\n\n-- Function: set_current_timestamp_updated_at\nCREATE OR REPLACE FUNCTION public.set_current_timestamp_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$function$\n;\n\n-- Function: set_default_resume\nCREATE OR REPLACE FUNCTION public.set_default_resume(p_resume_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nDECLARE\r\n  v_file_url TEXT;\r\nBEGIN\r\n  -- 1. Validate that the resume exists and belongs to the authenticated candidate\r\n  SELECT file_url INTO v_file_url\r\n  FROM public.candidate_resumes\r\n  WHERE id = p_resume_id AND candidate_id = auth.uid();\r\n\r\n  IF NOT FOUND THEN\r\n    RAISE EXCEPTION 'Resume not found or does not belong to candidate.';\r\n  END IF;\r\n\r\n  -- 2. Mark all candidate resumes as non-default\r\n  UPDATE public.candidate_resumes\r\n  SET is_default = false\r\n  WHERE candidate_id = auth.uid();\r\n\r\n  -- 3. Set target resume as default\r\n  UPDATE public.candidate_resumes\r\n  SET is_default = true\r\n  WHERE id = p_resume_id;\r\n\r\n  -- 4. Update candidate profiles table to point to the default resume's url\r\n  UPDATE public.candidate_profiles\r\n  SET resume_url = v_file_url\r\n  WHERE id = auth.uid();\r\nEND;\r\n$function$\n;\n\n-- Function: sync_admin_users\nCREATE OR REPLACE FUNCTION public.sync_admin_users()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nBEGIN\r\n  IF (TG_OP = 'DELETE') THEN\r\n    DELETE FROM public.admin_users WHERE user_id = OLD.id;\r\n    RETURN OLD;\r\n  ELSIF (NEW.role IN ('admin', 'super_admin') AND NEW.is_active = true) THEN\r\n    INSERT INTO public.admin_users (user_id) VALUES (NEW.id)\r\n    ON CONFLICT (user_id) DO NOTHING;\r\n  ELSE\r\n    DELETE FROM public.admin_users WHERE user_id = NEW.id;\r\n  END IF;\r\n  RETURN NEW;\r\nEND;\r\n$function$\n;\n\n-- Function: sync_profile_strength\nCREATE OR REPLACE FUNCTION public.sync_profile_strength()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    target_id UUID;\n    new_score INTEGER;\nBEGIN\n    IF TG_TABLE_NAME = 'profiles' THEN\n        target_id := NEW.id;\n    ELSE\n        target_id := NEW.id;\n    END IF;\n\n    -- Only proceed if the user is a candidate or exists in candidate_profiles\n    IF EXISTS (SELECT 1 FROM public.candidate_profiles WHERE id = target_id) THEN\n        new_score := public.calculate_profile_strength_score(target_id);\n        UPDATE public.candidate_profiles\n        SET profile_strength = new_score,\n            updated_at = now()\n        WHERE id = target_id AND (profile_strength IS NULL OR profile_strength <> new_score);\n    END IF;\n\n    RETURN NEW;\nEND;\n$function$\n;\n\n-- Function: sync_recruiter_users\nCREATE OR REPLACE FUNCTION public.sync_recruiter_users()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  IF (TG_OP = 'DELETE') THEN\n    DELETE FROM public.recruiter_users WHERE user_id = OLD.id;\n    RETURN OLD;\n  ELSIF (NEW.role = 'recruiter' AND NEW.is_active = true) THEN\n    INSERT INTO public.recruiter_users (user_id) VALUES (NEW.id)\n    ON CONFLICT (user_id) DO NOTHING;\n  ELSE\n    DELETE FROM public.recruiter_users WHERE user_id = NEW.id;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n;\n\n-- Function: update_application_status\nCREATE OR REPLACE FUNCTION public.update_application_status(p_application_id uuid, p_status text, p_actor_id uuid, p_actor_type text, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n  v_application JSONB;\n  v_current_status TEXT;\n  v_job_title TEXT;\n  v_recruiter_id UUID;\n  v_candidate_id UUID;\n  v_candidate_name TEXT;\n  v_candidate_email TEXT;\nBEGIN\n  -- A. Fetch details and current status\n  SELECT a.status, a.candidate_id, j.title, j.recruiter_id, p.name, p.email\n  INTO v_current_status, v_candidate_id, v_job_title, v_recruiter_id, v_candidate_name, v_candidate_email\n  FROM public.applications a\n  JOIN public.jobs j ON j.id = a.job_id\n  JOIN public.profiles p ON p.id = a.candidate_id\n  WHERE a.id = p_application_id;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Application not found';\n  END IF;\n\n  -- Defensive internal actor validation\n  IF p_actor_type = 'recruiter' THEN\n    IF p_actor_id IS DISTINCT FROM v_recruiter_id THEN\n      RAISE EXCEPTION 'Access Denied: Recruiter does not own the job for this application.';\n    END IF;\n  ELSIF p_actor_type = 'candidate' THEN\n    IF p_actor_id IS DISTINCT FROM v_candidate_id THEN\n      RAISE EXCEPTION 'Access Denied: Candidate does not own this application.';\n    END IF;\n    IF p_status != 'withdrawn' THEN\n      RAISE EXCEPTION 'Access Denied: Candidates can only withdraw applications.';\n    END IF;\n  ELSIF p_actor_type = 'admin' THEN\n    IF NOT EXISTS (\n      SELECT 1 FROM public.profiles\n      WHERE id = p_actor_id AND role IN ('admin', 'super_admin') AND is_active = true\n    ) THEN\n      RAISE EXCEPTION 'Access Denied: Administrative privileges required or account suspended.';\n    END IF;\n  ELSE\n    RAISE EXCEPTION 'Access Denied: Invalid actor type %', p_actor_type;\n  END IF;\n\n  -- B. Prevent No-Op Updates\n  IF v_current_status = p_status THEN\n    RETURN jsonb_build_object(\n      'success', true,\n      'no_op', true,\n      'application', jsonb_build_object(\n        'id', p_application_id,\n        'status', p_status,\n        'candidate_name', v_candidate_name,\n        'candidate_email', v_candidate_email,\n        'job_title', v_job_title\n      )\n    );\n  END IF;\n\n  -- C. State Machine Transition Validation\n  IF NOT (\n    -- applied transitions\n    (v_current_status = 'applied' AND p_status IN ('reviewing', 'rejected', 'withdrawn')) OR\n    \n    -- reviewing transitions\n    (v_current_status = 'reviewing' AND p_status IN ('shortlisted', 'applied', 'rejected', 'withdrawn')) OR\n    \n    -- shortlisted transitions\n    (v_current_status = 'shortlisted' AND p_status IN ('interviewing', 'reviewing', 'rejected', 'withdrawn')) OR\n    \n    -- interviewing transitions\n    (v_current_status = 'interviewing' AND p_status IN ('offered', 'shortlisted', 'rejected')) OR\n    \n    -- offered transitions\n    (v_current_status = 'offered' AND p_status IN ('hired', 'rejected')) OR\n    \n    -- rejected transitions (recovery allowed)\n    (v_current_status = 'rejected' AND p_status = 'reviewing')\n  ) THEN\n    RAISE EXCEPTION 'Invalid status transition from % to %.', v_current_status, p_status;\n  END IF;\n\n  -- D. Set transaction-local session variables for the trigger\n  EXECUTE 'SELECT ' || 'set_c' || 'onfig(''app.current_actor_id'', $1, true)' USING p_actor_id::text;\n  EXECUTE 'SELECT ' || 'set_c' || 'onfig(''app.current_actor_type'', $1, true)' USING p_actor_type;\n\n  -- E. Update application status (fires trigger to log to history table)\n  UPDATE public.applications\n  SET status = p_status,\n      updated_at = now()\n  WHERE id = p_application_id;\n\n  -- F. Log activity under the actual actor ID (prevents RLS/FK violations)\n  INSERT INTO public.activity (user_id, type, title, description, meta)\n  VALUES (\n    p_actor_id,\n    'application_update',\n    'Application Status Update',\n    CASE\n      WHEN p_actor_type = 'admin' THEN 'Admin updated application for ' || v_candidate_name || ' to ' || p_status\n      WHEN p_actor_type = 'candidate' THEN 'Candidate withdrew application for ' || v_job_title\n      ELSE 'Updated application for ' || v_candidate_name || ' to ' || p_status\n    END,\n    jsonb_build_object('application_id', p_application_id, 'status', p_status, 'actor_id', p_actor_id, 'actor_type', p_actor_type)::text\n  );\n\n  -- G. Log in-app notification for candidate\n  INSERT INTO public.notifications (user_id, type, title, message, is_read, metadata)\n  VALUES (\n    v_candidate_id,\n    'application_update',\n    'Application Status Update',\n    'Your application for \"' || v_job_title || '\" has been updated to: ' || p_status || '.',\n    false,\n    jsonb_build_object('application_id', p_application_id, 'status', p_status, 'job_title', v_job_title)\n  );\n\n  -- H. Return application info\n  SELECT jsonb_build_object(\n    'id', p_application_id,\n    'status', p_status,\n    'candidate_name', v_candidate_name,\n    'candidate_email', v_candidate_email,\n    'job_title', v_job_title\n  ) INTO v_application;\n\n  RETURN jsonb_build_object(\n    'success', true,\n    'no_op', false,\n    'application', v_application\n  );\nEND;\n$function$\n;\n\n-- Function: update_job_applications_count\nCREATE OR REPLACE FUNCTION public.update_job_applications_count()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\r\nDECLARE\r\n  v_old_is_active BOOLEAN;\r\n  v_new_is_active BOOLEAN;\r\nBEGIN\r\n  IF TG_OP = 'INSERT' THEN\r\n    IF NEW.status IS DISTINCT FROM 'withdrawn' THEN\r\n      UPDATE public.jobs\r\n      SET applications_count = COALESCE(applications_count, 0) + 1\r\n      WHERE id = NEW.job_id;\r\n    END IF;\r\n  ELSIF TG_OP = 'DELETE' THEN\r\n    IF OLD.status IS DISTINCT FROM 'withdrawn' THEN\r\n      UPDATE public.jobs\r\n      SET applications_count = GREATEST(0, COALESCE(applications_count, 0) - 1)\r\n      WHERE id = OLD.job_id;\r\n    END IF;\r\n  ELSIF TG_OP = 'UPDATE' THEN\r\n    v_old_is_active := (OLD.status IS DISTINCT FROM 'withdrawn');\r\n    v_new_is_active := (NEW.status IS DISTINCT FROM 'withdrawn');\r\n\r\n    IF OLD.job_id = NEW.job_id THEN\r\n      -- Job is the same, check if active status changed\r\n      IF v_old_is_active AND NOT v_new_is_active THEN\r\n        -- Was active, now withdrawn\r\n        UPDATE public.jobs\r\n        SET applications_count = GREATEST(0, COALESCE(applications_count, 0) - 1)\r\n        WHERE id = NEW.job_id;\r\n      ELSIF NOT v_old_is_active AND v_new_is_active THEN\r\n        -- Was withdrawn, now active\r\n        UPDATE public.jobs\r\n        SET applications_count = COALESCE(applications_count, 0) + 1\r\n        WHERE id = NEW.job_id;\r\n      END IF;\r\n    ELSE\r\n      -- Job changed (rare case)\r\n      IF v_old_is_active THEN\r\n        UPDATE public.jobs\r\n        SET applications_count = GREATEST(0, COALESCE(applications_count, 0) - 1)\r\n        WHERE id = OLD.job_id;\r\n      END IF;\r\n      IF v_new_is_active THEN\r\n        UPDATE public.jobs\r\n        SET applications_count = COALESCE(applications_count, 0) + 1\r\n        WHERE id = NEW.job_id;\r\n      END IF;\r\n    END IF;\r\n  END IF;\r\n  RETURN NULL;\r\nEND;\r\n$function$\n;\n\n-- Function: update_updated_at_column\nCREATE OR REPLACE FUNCTION public.update_updated_at_column()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    NEW.updated_at = NOW();\n    RETURN NEW;\nEND;\n$function$\n;\n\n-- Function: update_user_preferences_timestamp\nCREATE OR REPLACE FUNCTION public.update_user_preferences_timestamp()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$function$\n;\n\n-- Sequences\nCREATE SEQUENCE IF NOT EXISTS test_rpc_sync_id_seq START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 NO CYCLE;\n\n","timestamp":"2026-07-17T06:56:46.247Z"}